var FROTA_CONTEUDO_MODULO = "<style>\n#tplFrotaContainer {\n  color-scheme: dark;\n  --bg: #111827; --card: #1f2937; --panel: #1f2937; --input: #172033; --input-hover: #1d293a;\n  --text: #d9e2ec; --text-strong: #eef3f8; --muted: #9aa8b8; --muted-2: #7f8da0;\n  --border: #3a4657; --border-strong: #4a5870; --accent: #6fbf8f; --accent-2: #7aa7c7;\n  --success-bg: rgba(111,191,143,.14); --info-bg: rgba(122,167,199,.14);\n  --warning-bg: rgba(214,169,79,.14); --danger-bg: rgba(224,138,138,.13);\n  --shadow-soft: 0 8px 22px rgba(0,0,0,.18); --radius: 8px; --radius-sm: 6px;\n}\n#tplFrotaContainer * { box-sizing: border-box; }\n#tplFrotaContainer .hidden { display: none !important; }\n#tplFrotaContainer, #tplFrotaContainer body { font-family: \"Segoe UI\", Inter, Arial, sans-serif; background: #111827 !important; color: var(--text) !important; }\n#tplFrotaContainer .wrap { max-width: 1100px; margin: 0 auto; padding: 18px; }\n#tplFrotaContainer .header-card { background: #1f2937 !important; border: 1px solid var(--border); border-radius: var(--radius); padding: 14px 18px; box-shadow: var(--shadow-soft); margin-bottom: 14px; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 14px; }\n#tplFrotaContainer .title-area h1 { margin: 0; font-size: 19px; color: var(--text-strong); font-weight: 800; }\n#tplFrotaContainer .title-area p { margin: 5px 0 0; color: var(--muted); font-size: 13px; }\n#tplFrotaContainer .panel { background: #1f2937 !important; border-radius: var(--radius); padding: 18px; box-shadow: var(--shadow-soft); border: 1px solid var(--border); margin-bottom: 14px; }\n#tplFrotaContainer .panel h2 { margin: 0 0 14px; font-size: 14px; color: var(--text-strong) !important; border-bottom: 1px solid var(--border); padding-bottom: 10px; text-transform: uppercase; }\n#tplFrotaContainer label { display: block; font-size: 12px; color: var(--muted); margin: 10px 0 4px; }\n#tplFrotaContainer input[type=\"text\"], #tplFrotaContainer input:not([type]), #tplFrotaContainer input[type=\"number\"],\n#tplFrotaContainer input[type=\"file\"], #tplFrotaContainer select, #tplFrotaContainer textarea {\n  width: 100%; background: var(--input) !important; color: var(--text) !important; border: 1px solid var(--border);\n  border-radius: var(--radius-sm); padding: 9px 10px; font-size: 13px;\n}\n#tplFrotaContainer textarea { min-height: 60px; resize: vertical; }\n#tplFrotaContainer .form-row { display: flex; gap: 10px; align-items: flex-end; flex-wrap: wrap; }\n#tplFrotaContainer .form-row > * { flex: 1; min-width: 180px; }\n#tplFrotaContainer .grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; }\n#tplFrotaContainer .grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }\n#tplFrotaContainer .btn, #tplFrotaContainer .btn-primary { border: 1px solid var(--border-strong); background: var(--input); color: var(--text); border-radius: var(--radius-sm); padding: 9px 16px; font-weight: 700; font-size: 13px; cursor: pointer; margin-top: 10px; }\n#tplFrotaContainer .btn:hover { background: var(--input-hover); }\n#tplFrotaContainer .btn-primary { background: var(--accent); color: #0d1b12; border-color: var(--accent); }\n#tplFrotaContainer .btn-primary:hover { filter: brightness(1.08); }\n#tplFrotaContainer .btn-danger { background: var(--danger-bg); color: #f2b8b8; border-color: rgba(224,138,138,.42); }\n#tplFrotaContainer .btn-sm { padding: 5px 10px; font-size: 11.5px; margin-top: 0; }\n#tplFrotaContainer .alert-box { border-radius: var(--radius-sm); padding: 10px 12px; font-size: 12.5px; margin-top: 10px; }\n#tplFrotaContainer .alert-box.success { background: var(--success-bg); color: #b9dec8; border: 1px solid rgba(111,191,143,.34); }\n#tplFrotaContainer .alert-box.error { background: var(--danger-bg); color: #f2b8b8; border: 1px solid rgba(224,138,138,.42); }\n#tplFrotaContainer .alert-box.info { background: var(--info-bg); color: #bcd6ea; border: 1px solid rgba(122,167,199,.34); }\n#tplFrotaContainer .card { border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 12px; margin-bottom: 12px; background: #182233; }\n#tplFrotaContainer .checkbox-row {\n  display: grid; grid-template-columns: 16px 1fr; grid-template-rows: auto auto;\n  column-gap: 8px; row-gap: 4px; align-items: center; padding: 4px 6px; border-radius: var(--radius-sm);\n}\n#tplFrotaContainer .checkbox-row input[type=\"checkbox\"] {\n  -webkit-appearance: auto; appearance: auto;\n  width: 16px !important; height: 16px !important; min-width: 16px !important; min-height: 16px !important;\n  max-width: 16px !important; max-height: 16px !important; margin: 0; padding: 0;\n  accent-color: var(--accent); grid-column: 1; grid-row: 1; forced-color-adjust: none;\n}\n#tplFrotaContainer .checkbox-row label {\n  margin: 0; color: var(--text); font-size: 12.5px !important; font-weight: 400 !important;\n  text-transform: none !important; line-height: 1.3; grid-column: 2; grid-row: 1; cursor: pointer;\n}\n#tplFrotaContainer .checkbox-row .obs-input { display: none; grid-column: 1 / -1; grid-row: 2; width: 100%; }\n#tplFrotaContainer .checkbox-row.nao-conforme { background: var(--danger-bg); }\n#tplFrotaContainer .checkbox-row.nao-conforme .obs-input { display: block; }\n#tplFrotaContainer .linha-lista { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 6px 10px; padding: 7px 6px; border-radius: var(--radius-sm); border-bottom: 1px solid var(--border); }\n#tplFrotaContainer .linha-lista:last-child { border-bottom: none; }\n#tplFrotaContainer .linha-lista > span:first-child { flex: 1; min-width: 200px; }\n#tplFrotaContainer .checklist-grupo-titulo { font-size: 12.5px; font-weight: 700; color: var(--accent-2); margin: 14px 0 4px; text-transform: uppercase; letter-spacing: .03em; }\n#tplFrotaContainer .checklist-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 2px 12px; }\n#tplFrotaContainer table.resultado-table { width: 100%; border-collapse: collapse; margin-top: 10px; font-size: 11.5px; }\n#tplFrotaContainer table.resultado-table th, #tplFrotaContainer table.resultado-table td { border: 1px solid var(--border); padding: 5px 7px; text-align: center; }\n#tplFrotaContainer .tabela-acoes { display: inline-flex; flex-wrap: wrap; gap: 6px; align-items: center; justify-content: center; }\n#tplFrotaContainer table.resultado-table th { background: var(--info-bg); color: var(--text-strong); }\n#tplFrotaContainer .foto-thumb { display: inline-flex; flex-direction: column; gap: 4px; width: 140px; margin: 6px 8px 6px 0; vertical-align: top; }\n#tplFrotaContainer .foto-thumb img { width: 100%; height: 100px; object-fit: cover; border-radius: 4px; border: 1px solid var(--border); }\n#tplFrotaContainer .foto-thumb input { font-size: 11px; padding: 5px 6px; }\n#tplFrotaContainer .muted { color: var(--muted); font-size: 12px; }\n#tplFrotaContainer .tabela-wrap { overflow-x: auto; margin: 8px 0; }\n\n@media (max-width: 640px) {\n  #tplFrotaContainer .wrap { padding: 10px; }\n  #tplFrotaContainer .grid-2, #tplFrotaContainer .grid-3 { grid-template-columns: 1fr; }\n  #tplFrotaContainer .header-card { flex-direction: column; align-items: flex-start; }\n  #tplFrotaContainer table.resultado-table { display: block; overflow-x: auto; white-space: nowrap; }\n  #tplFrotaContainer .foto-thumb { width: 100%; }\n}\n\n/* Manual do Operador — mesmo padrão visual dos outros módulos do Portal */\n#tplFrotaContainer .manual-wrap { max-width: 900px; margin: 0 auto; padding: 18px 18px 60px; line-height: 1.6; }\n#tplFrotaContainer .manual-wrap h1 { font-size: 26px; margin-bottom: 4px; }\n#tplFrotaContainer .manual-wrap h2 { font-size: 19px; margin-top: 40px; padding-bottom: 8px; border-bottom: 1px solid var(--border); color: var(--text-strong); }\n#tplFrotaContainer .manual-wrap h3 { font-size: 15px; margin-top: 26px; color: var(--accent-2); }\n#tplFrotaContainer .manual-wrap p { color: var(--text); }\n#tplFrotaContainer .manual-wrap table { width: 100%; border-collapse: collapse; margin: 14px 0 22px; font-size: 13.5px; }\n#tplFrotaContainer .manual-wrap th, #tplFrotaContainer .manual-wrap td { border: 1px solid var(--border); padding: 8px 10px; text-align: left; vertical-align: top; }\n#tplFrotaContainer .manual-wrap th { background: #172033; color: var(--text-strong); }\n#tplFrotaContainer .manual-wrap tr:nth-child(even) td { background: rgba(255,255,255,0.02); }\n#tplFrotaContainer .callout { background: rgba(111,191,143,.14); border: 1px solid rgba(111,191,143,.35); border-left: 4px solid var(--accent); border-radius: var(--radius-sm); padding: 12px 14px; margin: 14px 0; font-size: 13.5px; }\n#tplFrotaContainer .callout strong { color: var(--text-strong); }\n#tplFrotaContainer .manual-wrap ol, #tplFrotaContainer .manual-wrap ul { padding-left: 22px; }\n#tplFrotaContainer .manual-wrap ol li, #tplFrotaContainer .manual-wrap ul li { margin-bottom: 6px; }\n#tplFrotaContainer .toc { background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius); padding: 16px 20px; margin-bottom: 30px; }\n#tplFrotaContainer .toc h2 { margin-top: 0; border-bottom: none; font-size: 15px; }\n#tplFrotaContainer .toc ol { columns: 2; column-gap: 30px; }\n#tplFrotaContainer .toc a { text-decoration: none; color: var(--accent-2); cursor: pointer; }\n#tplFrotaContainer .toc a:hover { text-decoration: underline; }\n#tplFrotaContainer .topo-link { display: inline-block; margin-top: 30px; }\n@media (max-width: 640px) { #tplFrotaContainer .toc ol { columns: 1; } }\n</style>\n<script>\nvar frotaState = {\n  veiculos: [], veiculosTodos: [], condutores: [], gruposChecklist: [], tiposManutencao: [], tiposDespesa: [], tiposDocumento: [], tiposCombustivel: [],\n  emAndamento: [], checklistRetirada: [], fotosRetirada: [], checklistDevolucao: [], fotosDevolucao: [],\n  movimentacaoDevolucaoAtual: null, historico: null, documentos: [], multas: [], abastecimentos: []\n};\n\nfunction tplFrota_chamarApi(fn, payload) {\n  return new Promise(function(resolve, reject) {\n    if (typeof SGO_iniciarCarregamento_ === 'function') SGO_iniciarCarregamento_();\n    google.script.run\n      .withSuccessHandler(function(res) { if (typeof SGO_finalizarCarregamento_ === 'function') SGO_finalizarCarregamento_(); resolve(res); })\n      .withFailureHandler(function(err) { if (typeof SGO_finalizarCarregamento_ === 'function') SGO_finalizarCarregamento_(); reject(err); })\n      .Frota_apiDispatch({ sessionId: SGO_getSessionId(), fn: fn, payload: payload || {} });\n  });\n}\n\nfunction tplFrota_chamarApiSegundoPlano_(fn, payload, aoTerminar) {\n  google.script.run\n    .withSuccessHandler(function(res) { aoTerminar(null, res); })\n    .withFailureHandler(function(err) { aoTerminar(err, null); })\n    .Frota_apiDispatch({ sessionId: SGO_getSessionId(), fn: fn, payload: payload || {} });\n}\n\nfunction tplFrota_chamarApiSilencioso_(fn, payload) {\n  return new Promise(function(resolve, reject) {\n    google.script.run\n      .withSuccessHandler(resolve)\n      .withFailureHandler(reject)\n      .Frota_apiDispatch({ sessionId: SGO_getSessionId(), fn: fn, payload: payload || {} });\n  });\n}\n\nfunction tplFrota_uploadFotosEmParalelo_(placa, fotos) {\n  if (!fotos || !fotos.length) return Promise.resolve([]);\n  return Promise.all(fotos.map(function(f) {\n    return tplFrota_chamarApiSilencioso_('apiUploadFotoVeiculo', { placa: placa, base64: f.base64, mimeType: f.mimeType, nomeArquivo: f.nomeArquivo, legenda: f.legenda });\n  })).then(function(respostas) {\n    return respostas.map(function(r) { return { link: r.link, legenda: r.legenda }; });\n  });\n}\n\nfunction tplFrota_toast_(sucesso, titulo, detalhe) {\n  if (typeof frotaToastEnvio_ === 'function') { frotaToastEnvio_(sucesso, titulo, detalhe); return; }\n  alert(titulo + (detalhe ? ' - ' + detalhe : ''));\n}\n\nfunction tplFrota_preencherAgora_(qual) {\n  var agora = new Date();\n  var data = ('0' + agora.getDate()).slice(-2) + '/' + ('0' + (agora.getMonth() + 1)).slice(-2) + '/' + agora.getFullYear();\n  var hora = ('0' + agora.getHours()).slice(-2) + ':' + ('0' + agora.getMinutes()).slice(-2);\n  var prefixo = qual === 'retirada' ? 'tplFrota_r_' : 'tplFrota_d_';\n  var elData = document.getElementById(prefixo + 'data');\n  var elHora = document.getElementById(prefixo + 'hora');\n  if (elData) elData.value = data;\n  if (elHora) elHora.value = hora;\n}\n\nfunction tplFrota_msg(containerId, tipo, texto) {\n  var el = document.getElementById(containerId);\n  if (!el) return;\n  el.innerHTML = '<div class=\"alert-box ' + tipo + '\">' + texto + '</div>';\n}\nfunction tplFrota_erro(containerId, err) {\n  var msg = (err && err.message) ? err.message : String(err);\n  tplFrota_msg(containerId, 'error', msg);\n}\nfunction tplFrota_lerArquivoComoBase64_(file) {\n  return new Promise(function(resolve) {\n    var reader = new FileReader();\n    reader.onload = function(e) {\n      var resultado = e.target.result || '';\n      var base64 = resultado.indexOf(',') !== -1 ? resultado.split(',')[1] : resultado;\n      resolve({ base64: base64, mimeType: file.type || 'image/jpeg', nomeArquivo: file.name });\n    };\n    reader.onerror = function() { resolve(null); };\n    reader.readAsDataURL(file);\n  });\n}\n\nfunction tplFrota_renderReal_() {\n  var container = document.getElementById('tplFrotaContainer');\n  if (!container) return;\n\n  container.innerHTML =\n    '<div id=\"tplFrota_viewModulo\">' +\n    '<div class=\"wrap\">' +\n    '  <div class=\"header-card\">' +\n    '    <div class=\"title-area\"><h1>Frota</h1><p>Retirada/devolução de veículos com checklist, manutenção com alerta de vencimento, despesas e histórico.</p></div>' +\n    '    <button type=\"button\" class=\"btn\" onclick=\"tplFrota_abrirManual_()\">Manual do Operador</button>' +\n    '  </div>' +\n\n    '  <div class=\"panel\">' +\n    '    <h2>Relatório da Frota (PDF)</h2>' +\n    '    <p class=\"muted\" style=\"margin-top:-6px;\">Histórico de uso, abastecimento, despesas, manutenções, documentos, multas/ocorrências, resumo gerencial, conclusão e pendências — por veículo ou de toda a frota, pronto pra imprimir e fica salvo no Drive.</p>' +\n    '    <div class=\"grid-3\">' +\n    '      <div><label>Veículo</label><select id=\"tplFrota_rel_veiculo\"><option value=\"\">Toda a frota (relatório geral)</option></select></div>' +\n    '      <div><label>Data início</label><input id=\"tplFrota_rel_inicio\" placeholder=\"dd/mm/aaaa\"></div>' +\n    '      <div><label>Data fim</label><input id=\"tplFrota_rel_fim\" placeholder=\"dd/mm/aaaa\"></div>' +\n    '    </div>' +\n    '    <div class=\"grid-3\">' +\n    '      <div style=\"display:flex;align-items:flex-end;\"><button class=\"btn-primary\" onclick=\"tplFrota_gerarRelatorio()\" style=\"width:100%;\">Gerar Relatório</button></div>' +\n    '    </div>' +\n    '    <div id=\"tplFrota_relatorioStatus\"></div>' +\n    '  </div>' +\n\n    '  <div class=\"panel\" id=\"tplFrota_panel_alertas\">' +\n    '    <h2>Avisos de manutenção</h2>' +\n    '    <div id=\"tplFrota_alertasWrap\" class=\"muted\">Carregando...</div>' +\n    '  </div>' +\n\n    '  <div class=\"panel\">' +\n    '    <h2>Retiradas em andamento</h2>' +\n    '    <div id=\"tplFrota_situacao\"></div>' +\n    '    <div id=\"tplFrota_emAndamentoWrap\" class=\"muted\">Carregando...</div>' +\n    '  </div>' +\n\n    '  <div class=\"panel\">' +\n    '    <h2>Veículos</h2>' +\n    '    <div id=\"tplFrota_veiculosTabela\" class=\"muted\">Carregando...</div>' +\n    '    <button class=\"btn\" id=\"tplFrota_btnCadastrarVeiculo\" onclick=\"tplFrota_abrirNovoVeiculo()\">+ Cadastrar novo veículo</button>' +\n    '    <div id=\"tplFrota_veiculoNovo\" class=\"hidden card\">' +\n    '      <div class=\"grid-3\">' +\n    '        <div><label>Placa</label><input id=\"tplFrota_v_placa\" placeholder=\"ABC1D23\"></div>' +\n    '        <div><label>Modelo</label><input id=\"tplFrota_v_modelo\"></div>' +\n    '        <div><label>Marca</label><input id=\"tplFrota_v_marca\"></div>' +\n    '      </div>' +\n    '      <div class=\"grid-3\">' +\n    '        <div><label>Ano</label><input id=\"tplFrota_v_ano\"></div>' +\n    '        <div><label>Cor</label><input id=\"tplFrota_v_cor\"></div>' +\n    '        <div><label>KM atual</label><input id=\"tplFrota_v_km\" value=\"0\"></div>' +\n    '      </div>' +\n    '      <button class=\"btn-primary\" onclick=\"tplFrota_criarVeiculo()\">Salvar veículo</button>' +\n    '      <div id=\"tplFrota_veiculoStatus\"></div>' +\n    '    </div>' +\n    '    <div id=\"tplFrota_veiculoEditar\" class=\"hidden card\">' +\n    '      <h3>Editar veículo</h3>' +\n    '      <input type=\"hidden\" id=\"tplFrota_ve_id\">' +\n    '      <div class=\"grid-3\">' +\n    '        <div><label>Placa</label><input id=\"tplFrota_ve_placa\"></div>' +\n    '        <div><label>Modelo</label><input id=\"tplFrota_ve_modelo\"></div>' +\n    '        <div><label>Marca</label><input id=\"tplFrota_ve_marca\"></div>' +\n    '      </div>' +\n    '      <div class=\"grid-3\">' +\n    '        <div><label>Ano</label><input id=\"tplFrota_ve_ano\"></div>' +\n    '        <div><label>Cor</label><input id=\"tplFrota_ve_cor\"></div>' +\n    '        <div><label>KM atual</label><input id=\"tplFrota_ve_km\"></div>' +\n    '      </div>' +\n    '      <button class=\"btn-primary\" onclick=\"tplFrota_salvarEdicaoVeiculo()\">Salvar edição</button> ' +\n    '      <button class=\"btn\" onclick=\"tplFrota_fecharEditarVeiculo()\">Cancelar</button>' +\n    '      <div id=\"tplFrota_veiculoEditarStatus\"></div>' +\n    '    </div>' +\n    '  </div>' +\n\n    '  <div class=\"panel\">' +\n    '    <h2>Condutores</h2>' +\n    '    <div id=\"tplFrota_condutoresLista\" class=\"muted\">Carregando...</div>' +\n    '    <button class=\"btn\" onclick=\"tplFrota_abrirNovoCondutor()\">+ Cadastrar novo condutor</button>' +\n    '    <div id=\"tplFrota_condutorNovo\" class=\"hidden card\">' +\n    '      <div class=\"grid-2\">' +\n    '        <div><label>Vincular a um usuário do SGO (opcional)</label><select id=\"tplFrota_c_usuario\" onchange=\"tplFrota_aoSelecionarUsuarioCondutor_()\"><option value=\"\">— Sem login (motorista avulso) —</option></select></div>' +\n    '        <div><label>Nome</label><input id=\"tplFrota_c_nome\"></div>' +\n    '      </div>' +\n    '      <div class=\"grid-2\">' +\n    '        <div><label>Telefone</label><input id=\"tplFrota_c_telefone\"></div>' +\n    '        <div><label>CNH (opcional)</label><input id=\"tplFrota_c_cnh\"></div>' +\n    '      </div>' +\n    '      <div class=\"grid-2\">' +\n    '        <div><label>Validade da CNH (opcional)</label><input id=\"tplFrota_c_cnhValidade\" placeholder=\"dd/mm/aaaa\"></div>' +\n    '        <div><label>Arquivo da CNH (opcional)</label><input type=\"file\" id=\"tplFrota_c_cnhArquivo\" accept=\"image/*,application/pdf\"></div>' +\n    '      </div>' +\n    '      <button class=\"btn-primary\" onclick=\"tplFrota_criarCondutor()\">Salvar condutor</button>' +\n    '      <div id=\"tplFrota_condutorStatus\"></div>' +\n    '    </div>' +\n    '  </div>' +\n\n    '  <div class=\"panel\">' +\n    '    <h2>Retirar veículo</h2>' +\n    '    <div class=\"grid-2\">' +\n    '      <div><label>Veículo</label><select id=\"tplFrota_r_veiculo\"></select></div>' +\n    '      <div><label>Condutor</label><select id=\"tplFrota_r_condutor\"></select></div>' +\n    '    </div>' +\n    '    <div class=\"grid-3\">' +\n    '      <div><label>Data de saída</label><input id=\"tplFrota_r_data\" placeholder=\"dd/mm/aaaa\"></div>' +\n    '      <div><label>Hora de saída</label><input id=\"tplFrota_r_hora\" placeholder=\"hh:mm\"></div>' +\n    '      <div><label>KM de saída</label><input id=\"tplFrota_r_km\"></div>' +\n    '    </div>' +\n    '    <button type=\"button\" class=\"btn btn-sm\" onclick=\"tplFrota_preencherAgora_(\\'retirada\\')\">Usar data/hora atual</button>' +\n    '    <label>Finalidade</label><input id=\"tplFrota_r_finalidade\" placeholder=\"Ex.: visita técnica ao cliente X\">' +\n    '    <div class=\"checklist-grupo-titulo\">Checklist de vistoria (retirada)</div>' +\n    '    <div id=\"tplFrota_r_checklist\"></div>' +\n    '    <label>Fotos (opcional)</label>' +\n    '    <input type=\"file\" id=\"tplFrota_r_fotosInput\" multiple accept=\"image/*\" onchange=\"tplFrota_onFotosSelecionadas_(\\'retirada\\')\">' +\n    '    <div id=\"tplFrota_r_fotosLista\" style=\"margin-top:8px;\"></div>' +\n    '    <button class=\"btn-primary\" onclick=\"tplFrota_registrarRetirada()\">Registrar Retirada</button>' +\n    '    <div id=\"tplFrota_retiradaStatus\"></div>' +\n    '  </div>' +\n\n    '  <div class=\"panel hidden\" id=\"tplFrota_panel_devolucao\">' +\n    '    <h2>Devolver veículo</h2>' +\n    '    <div id=\"tplFrota_devolucaoInfo\" class=\"muted\"></div>' +\n    '    <div class=\"grid-3\">' +\n    '      <div><label>Data de chegada</label><input id=\"tplFrota_d_data\" placeholder=\"dd/mm/aaaa\"></div>' +\n    '      <div><label>Hora de chegada</label><input id=\"tplFrota_d_hora\" placeholder=\"hh:mm\"></div>' +\n    '      <div><label>KM de chegada</label><input id=\"tplFrota_d_km\"></div>' +\n    '    </div>' +\n    '    <button type=\"button\" class=\"btn btn-sm\" onclick=\"tplFrota_preencherAgora_(\\'devolucao\\')\">Usar data/hora atual</button>' +\n    '    <div class=\"checklist-grupo-titulo\">Checklist de vistoria (devolução)</div>' +\n    '    <div id=\"tplFrota_d_checklist\"></div>' +\n    '    <label>Observações</label><textarea id=\"tplFrota_d_observacoes\"></textarea>' +\n    '    <label>Fotos (opcional)</label>' +\n    '    <input type=\"file\" id=\"tplFrota_d_fotosInput\" multiple accept=\"image/*\" onchange=\"tplFrota_onFotosSelecionadas_(\\'devolucao\\')\">' +\n    '    <div id=\"tplFrota_d_fotosLista\" style=\"margin-top:8px;\"></div>' +\n    '    <button class=\"btn-primary\" onclick=\"tplFrota_registrarDevolucao()\">Registrar Devolução</button>' +\n    '    <button class=\"btn\" onclick=\"tplFrota_cancelarDevolucao_()\">Cancelar</button>' +\n    '    <div id=\"tplFrota_devolucaoStatus\"></div>' +\n    '  </div>' +\n\n    '  <div class=\"panel\">' +\n    '    <h2>Registrar manutenção</h2>' +\n    '    <div class=\"grid-2\">' +\n    '      <div><label>Veículo</label><select id=\"tplFrota_m_veiculo\"></select></div>' +\n    '      <div><label>Tipo</label><select id=\"tplFrota_m_tipo\" onchange=\"tplFrota_aoTrocarTipoManutencao_()\"></select></div>' +\n    '    </div>' +\n    '    <div class=\"grid-3\">' +\n    '      <div><label>Data</label><input id=\"tplFrota_m_data\" placeholder=\"dd/mm/aaaa\"></div>' +\n    '      <div><label>KM na manutenção</label><input id=\"tplFrota_m_km\"></div>' +\n    '      <div><label>Custo (R$)</label><input id=\"tplFrota_m_custo\"></div>' +\n    '    </div>' +\n    '    <div class=\"grid-2\">' +\n    '      <div><label>Oficina/Fornecedor</label><input id=\"tplFrota_m_oficina\"></div>' +\n    '      <div><label>Descrição</label><input id=\"tplFrota_m_descricao\"></div>' +\n    '    </div>' +\n    '    <div class=\"grid-2\">' +\n    '      <div><label>Próxima troca — KM (opcional)</label><input id=\"tplFrota_m_proximaKm\"></div>' +\n    '      <div><label>Próxima troca — Data (opcional)</label><input id=\"tplFrota_m_proximaData\" placeholder=\"dd/mm/aaaa\"></div>' +\n    '    </div>' +\n    '    <button class=\"btn-primary\" onclick=\"tplFrota_registrarManutencao()\">Registrar Manutenção</button>' +\n    '    <div id=\"tplFrota_manutencaoStatus\"></div>' +\n    '  </div>' +\n\n    \n\n    '  <div class=\"panel\">' +\n    '    <h2>Registrar parada</h2>' +\n    '    <div class=\"grid-1\"><label>Veículo</label><select id=\"tplFrota_p_veiculo\"></select></div>' +\n    '    <div class=\"grid-2\">' +\n    '      <div><label>Data início</label><input id=\"tplFrota_p_dataInicio\" placeholder=\"dd/mm/aaaa\"></div>' +\n    '      <div><label>Data fim (opcional)</label><input id=\"tplFrota_p_dataFim\" placeholder=\"dd/mm/aaaa\"></div>' +\n    '    </div>' +\n    '    <label>Motivo</label><input id=\"tplFrota_p_motivo\" placeholder=\"Ex.: acidente, pane, revisão de garantia\">' +\n    '    <label>Descrição</label><textarea id=\"tplFrota_p_descricao\"></textarea>' +\n    '    <button class=\"btn-primary\" onclick=\"tplFrota_registrarParada()\">Registrar Parada</button>' +\n    '    <div id=\"tplFrota_paradaStatus\"></div>' +\n    '  </div>' +\n\n    '  <div class=\"panel\">' +\n    '    <h2>Histórico do veículo</h2>' +\n    '    <div class=\"form-row\">' +\n    '      <select id=\"tplFrota_h_veiculo\"></select>' +\n    '      <button class=\"btn\" onclick=\"tplFrota_buscarHistorico()\">Buscar</button>' +\n    '    </div>' +\n    '    <div id=\"tplFrota_historicoWrap\"></div>' +\n    '  </div>' +\n\n    '  <div class=\"panel\">' +\n    '    <h2>Documentos do veículo</h2>' +\n    '    <div class=\"form-row\">' +\n    '      <div><label>Filtrar por veículo</label><select id=\"tplFrota_df_veiculo\" onchange=\"tplFrota_carregarDocumentos_()\"></select></div>' +\n    '    </div>' +\n    '    <div id=\"tplFrota_documentosTabela\" class=\"muted\">Carregando...</div>' +\n    '    <button class=\"btn\" onclick=\"tplFrota_abrirNovoDocumento()\">+ Anexar documento</button>' +\n    '    <div id=\"tplFrota_documentoNovo\" class=\"hidden card\">' +\n    '      <div class=\"grid-2\">' +\n    '        <div><label>Veículo</label><select id=\"tplFrota_dc_veiculo\"></select></div>' +\n    '        <div><label>Tipo de documento</label><select id=\"tplFrota_dc_tipo\"></select></div>' +\n    '      </div>' +\n    '      <div class=\"grid-2\">' +\n    '        <div><label>Validade (opcional)</label><input id=\"tplFrota_dc_validade\" placeholder=\"dd/mm/aaaa\"></div>' +\n    '        <div><label>Arquivo</label><input type=\"file\" id=\"tplFrota_dc_arquivoInput\" accept=\"image/*,application/pdf\"></div>' +\n    '      </div>' +\n    '      <label>Observações (opcional)</label><input id=\"tplFrota_dc_observacoes\">' +\n    '      <button class=\"btn-primary\" onclick=\"tplFrota_uploadDocumento()\">Salvar documento</button>' +\n    '      <div id=\"tplFrota_documentoStatus\"></div>' +\n    '    </div>' +\n    '  </div>' +\n\n    '  <div class=\"panel\">' +\n    '    <h2>Multas</h2>' +\n    '    <div class=\"form-row\">' +\n    '      <div><label>Filtrar por veículo</label><select id=\"tplFrota_mf_veiculo\" onchange=\"tplFrota_carregarMultas_()\"></select></div>' +\n    '    </div>' +\n    '    <div id=\"tplFrota_multasTabela\" class=\"muted\">Carregando...</div>' +\n    '    <button class=\"btn\" onclick=\"tplFrota_abrirNovaMulta()\">+ Registrar multa</button>' +\n    '    <div id=\"tplFrota_multaNovo\" class=\"hidden card\">' +\n    '      <div class=\"grid-2\">' +\n    '        <div><label>Veículo</label><select id=\"tplFrota_mu_veiculo\"></select></div>' +\n    '        <div><label>Órgão autuador</label><input id=\"tplFrota_mu_orgao\" placeholder=\"Ex.: DETRAN-RJ, PRF...\"></div>' +\n    '      </div>' +\n    '      <div class=\"grid-3\">' +\n    '        <div><label>Data da infração</label><input id=\"tplFrota_mu_data\" placeholder=\"dd/mm/aaaa\"></div>' +\n    '        <div><label>Hora da infração</label><input id=\"tplFrota_mu_hora\" placeholder=\"hh:mm\"></div>' +\n    '        <div><label>Nº do AIT (opcional)</label><input id=\"tplFrota_mu_ait\"></div>' +\n    '      </div>' +\n    '      <div class=\"grid-2\">' +\n    '        <div><label>Local</label><input id=\"tplFrota_mu_local\"></div>' +\n    '        <div><label>Descrição da infração</label><input id=\"tplFrota_mu_descricao\" placeholder=\"Ex.: excesso de velocidade\"></div>' +\n    '      </div>' +\n    '      <div class=\"grid-3\">' +\n    '        <div><label>Valor (R$)</label><input id=\"tplFrota_mu_valor\"></div>' +\n    '        <div><label>Pontos (opcional)</label><input id=\"tplFrota_mu_pontos\"></div>' +\n    '        <div><label>Vencimento (opcional)</label><input id=\"tplFrota_mu_vencimento\" placeholder=\"dd/mm/aaaa\"></div>' +\n    '      </div>' +\n    '      <label>Documento da notificação (opcional)</label><input type=\"file\" id=\"tplFrota_mu_arquivoInput\" accept=\"image/*,application/pdf\">' +\n    '      <label>Observações</label><input id=\"tplFrota_mu_observacoes\">' +\n    '      <button class=\"btn-primary\" onclick=\"tplFrota_registrarMulta()\">Salvar multa</button>' +\n    '      <div id=\"tplFrota_multaStatus\"></div>' +\n    '    </div>' +\n    '  </div>' +\n\n    '  <div class=\"panel\">' +\n    '    <h2>Abastecimentos</h2>' +\n    '    <div class=\"form-row\">' +\n    '      <div><label>Filtrar por veículo</label><select id=\"tplFrota_af_veiculo\" onchange=\"tplFrota_carregarAbastecimentos_()\"></select></div>' +\n    '    </div>' +\n    '    <div id=\"tplFrota_abastecimentosTabela\" class=\"muted\">Carregando...</div>' +\n    '    <button class=\"btn\" onclick=\"tplFrota_abrirNovoAbastecimento()\">+ Registrar abastecimento</button>' +\n    '    <div id=\"tplFrota_abastecimentoNovo\" class=\"hidden card\">' +\n    '      <div class=\"grid-3\">' +\n    '        <div><label>Veículo</label><select id=\"tplFrota_ab_veiculo\"></select></div>' +\n    '        <div><label>Condutor (opcional)</label><select id=\"tplFrota_ab_condutor\"><option value=\"\">—</option></select></div>' +\n    '        <div><label>Data</label><input id=\"tplFrota_ab_data\" placeholder=\"dd/mm/aaaa\"></div>' +\n    '      </div>' +\n    '      <div class=\"grid-3\">' +\n    '        <div><label>KM no abastecimento</label><input id=\"tplFrota_ab_km\"></div>' +\n    '        <div><label>Tipo de combustível</label><select id=\"tplFrota_ab_tipo\"></select></div>' +\n    '        <div><label>Litros</label><input id=\"tplFrota_ab_litros\"></div>' +\n    '      </div>' +\n    '      <div class=\"grid-3\">' +\n    '        <div><label>Valor total (R$)</label><input id=\"tplFrota_ab_valor\"></div>' +\n    '        <div><label>Posto</label><input id=\"tplFrota_ab_posto\"></div>' +\n    '        <div><label>Comprovante (opcional)</label><input type=\"file\" id=\"tplFrota_ab_arquivoInput\" accept=\"image/*,application/pdf\"></div>' +\n    '      </div>' +\n    '      <button class=\"btn-primary\" onclick=\"tplFrota_registrarAbastecimento()\">Salvar abastecimento</button>' +\n    '      <div id=\"tplFrota_abastecimentoStatus\"></div>' +\n    '    </div>' +\n    '  </div>' +\n\n    '  </div>' +\n    '</div>' +\n    '<div id=\"tplFrota_viewManual\" style=\"display:none\">' + tplFrota_manualHtml_() + '</div>';\n\n  tplFrota_preencherAgora_('retirada');\n  tplFrota_definirDatasRelatorioPadrao_();\n  tplFrota_carregarTudo_();\n}\n\nfunction tplFrota_definirDatasRelatorioPadrao_() {\n  var hoje = new Date();\n  var trintaDiasAtras = new Date(hoje.getTime() - 30 * 86400000);\n  function fmt(d) { return ('0' + d.getDate()).slice(-2) + '/' + ('0' + (d.getMonth() + 1)).slice(-2) + '/' + d.getFullYear(); }\n  var elInicio = document.getElementById('tplFrota_rel_inicio');\n  var elFim = document.getElementById('tplFrota_rel_fim');\n  if (elInicio) elInicio.value = fmt(trintaDiasAtras);\n  if (elFim) elFim.value = fmt(hoje);\n}\n\nfunction tplFrota_gerarRelatorio() {\n  var payload = {\n    veiculoId: document.getElementById('tplFrota_rel_veiculo').value,\n    dataInicio: document.getElementById('tplFrota_rel_inicio').value,\n    dataFim: document.getElementById('tplFrota_rel_fim').value\n  };\n  var novaJanela = window.open('', '_blank');\n  if (novaJanela) {\n    novaJanela.document.write('<p style=\"font-family:Arial,sans-serif;padding:40px;color:#374151;\">Gerando relatório da frota, aguarde...</p>');\n  }\n  tplFrota_msg('tplFrota_relatorioStatus', 'info', 'Gerando relatório — isto pode levar alguns segundos (a IA está interpretando os dados)...');\n  tplFrota_chamarApi('apiGerarRelatorio', payload).then(function(res) {\n    if (novaJanela) {\n      novaJanela.document.open();\n      novaJanela.document.write(res.html);\n      novaJanela.document.close();\n    }\n    tplFrota_msg('tplFrota_relatorioStatus', 'success', 'Relatório gerado com sucesso — aberto em nova aba, pronto para Ctrl+P. Cópia salva no Drive: <a href=\"' + res.link + '\" target=\"_blank\" rel=\"noopener\">abrir PDF salvo</a>');\n  }).catch(function(err) {\n    if (novaJanela) novaJanela.close();\n    tplFrota_erro('tplFrota_relatorioStatus', err);\n  });\n}\n\nfunction tplFrota_abrirManual_() {\n  var viewModulo = document.getElementById('tplFrota_viewModulo');\n  var viewManual = document.getElementById('tplFrota_viewManual');\n  if (viewModulo) viewModulo.style.display = 'none';\n  if (viewManual) viewManual.style.display = '';\n}\nfunction tplFrota_voltarDoManual_() {\n  var viewModulo = document.getElementById('tplFrota_viewModulo');\n  var viewManual = document.getElementById('tplFrota_viewManual');\n  if (viewManual) viewManual.style.display = 'none';\n  if (viewModulo) viewModulo.style.display = '';\n}\nfunction tplFrota_irParaSecao_(id) {\n  var el = document.getElementById(id);\n  if (el && el.scrollIntoView) el.scrollIntoView({ behavior: 'smooth', block: 'start' });\n}\n\n// ---------------- Carregamento inicial ----------------\nfunction tplFrota_carregarTudo_() {\n  tplFrota_chamarApi('apiPing').then(function(res) {\n    frotaState.gruposChecklist = res.gruposChecklist || [];\n    frotaState.tiposManutencao = res.tiposManutencao || [];\n    frotaState.tiposDespesa = res.tiposDespesa || [];\n    frotaState.tiposDocumento = res.tiposDocumento || [];\n    frotaState.tiposCombustivel = res.tiposCombustivel || [];\n    tplFrota_renderChecklist_('tplFrota_r_checklist');\n    tplFrota_renderChecklist_('tplFrota_d_checklist');\n    tplFrota_popularSelect_('tplFrota_m_tipo', frotaState.tiposManutencao.map(function(t) { return { value: t.codigo, label: t.label }; }));\n    tplFrota_popularSelect_('tplFrota_dc_tipo', frotaState.tiposDocumento.map(function(t) { return { value: t, label: t }; }));\n    tplFrota_popularSelect_('tplFrota_ab_tipo', frotaState.tiposCombustivel.map(function(t) { return { value: t, label: t }; }));\n  }).catch(function(err) { console.error(err); });\n\n  tplFrota_carregarVeiculos_();\n  tplFrota_carregarCondutores_();\n  tplFrota_carregarEmAndamento_();\n  tplFrota_carregarAlertas_();\n  tplFrota_carregarAbastecimentos_();\n  tplFrota_carregarDocumentos_();\n  tplFrota_carregarMultas_();\n}\n\nfunction tplFrota_popularSelect_(id, opcoes) {\n  var sel = document.getElementById(id);\n  if (!sel) return;\n  sel.innerHTML = opcoes.map(function(o) { return '<option value=\"' + o.value + '\">' + o.label + '</option>'; }).join('');\n}\n\nfunction tplFrota_renderChecklist_(containerId) {\n  var el = document.getElementById(containerId);\n  if (!el) return;\n  el.innerHTML = frotaState.gruposChecklist.map(function(g) {\n    var itens = g.itens.map(function(item) {\n      var idSafe = (containerId + '_' + g.grupo + '_' + item).replace(/[^a-zA-Z0-9]/g, '_');\n      return '<div class=\"checkbox-row\"><input type=\"checkbox\" id=\"' + idSafe + '\" checked data-grupo=\"' + g.grupo + '\" data-item=\"' + item + '\" onchange=\"tplFrota_alternarObsChecklist_(this)\">' +\n        '<label for=\"' + idSafe + '\">' + item + '</label>' +\n        '<input type=\"text\" class=\"obs-input\" placeholder=\"Descreva o problema encontrado\" data-obs-de=\"' + idSafe + '\"></div>';\n    }).join('');\n    return '<div class=\"checklist-grupo-titulo\">' + g.grupo + '</div><div class=\"checklist-grid\">' + itens + '</div>';\n  }).join('');\n}\n\n// Item começa marcado como OK (comportamento já existente: \"cada item já\n// vem marcado como OK, desmarque o que estiver com problema\"). O campo de\n// observação só precisa aparecer quando o item é desmarcado — mantendo o\n// padrão descrito, só que sem ocupar espaço à toa quando está tudo OK.\nfunction tplFrota_alternarObsChecklist_(checkbox) {\n  var row = checkbox.closest('.checkbox-row');\n  if (!row) return;\n  row.classList.toggle('nao-conforme', !checkbox.checked);\n}\n\nfunction tplFrota_coletarChecklist_(containerId) {\n  var el = document.getElementById(containerId);\n  if (!el) return [];\n  var checkboxes = el.querySelectorAll('input[type=\"checkbox\"]');\n  var lista = [];\n  checkboxes.forEach(function(cb) {\n    var obsInput = el.querySelector('input[data-obs-de=\"' + cb.id + '\"]');\n    lista.push({ grupo: cb.getAttribute('data-grupo'), item: cb.getAttribute('data-item'), ok: cb.checked, observacao: obsInput ? obsInput.value : '' });\n  });\n  return lista;\n}\n\n// ---------------- Veículos ----------------\nfunction tplFrota_carregarVeiculos_() {\n  return tplFrota_chamarApi('apiListarVeiculosTodos').then(function(res) {\n    frotaState.veiculosTodos = res.items || [];\n    frotaState.veiculos = frotaState.veiculosTodos.filter(function(v) { return v.STATUS !== 'INATIVO'; });\n    tplFrota_renderVeiculosTabela_();\n    var disponiveis = frotaState.veiculos.filter(function(v) { return v.SITUACAO === 'DISPONIVEL'; });\n    tplFrota_popularSelect_('tplFrota_r_veiculo', disponiveis.map(function(v) { return { value: v.ID, label: v.PLACA + ' — ' + (v.MODELO || '') }; }));\n    tplFrota_popularSelect_('tplFrota_m_veiculo', frotaState.veiculos.map(function(v) { return { value: v.ID, label: v.PLACA + ' — ' + (v.MODELO || '') }; }));\n    tplFrota_popularSelect_('tplFrota_de_veiculo', frotaState.veiculos.map(function(v) { return { value: v.ID, label: v.PLACA + ' — ' + (v.MODELO || '') }; }));\n    tplFrota_popularSelect_('tplFrota_p_veiculo', frotaState.veiculos.map(function(v) { return { value: v.ID, label: v.PLACA + ' — ' + (v.MODELO || '') }; }));\n    tplFrota_popularSelect_('tplFrota_h_veiculo', frotaState.veiculosTodos.map(function(v) { return { value: v.ID, label: v.PLACA + ' — ' + (v.MODELO || '') }; }));\n    tplFrota_popularSelect_('tplFrota_dc_veiculo', frotaState.veiculos.map(function(v) { return { value: v.ID, label: v.PLACA + ' — ' + (v.MODELO || '') }; }));\n    tplFrota_popularSelect_('tplFrota_df_veiculo', [{ value: '', label: 'Todos os veículos' }].concat(frotaState.veiculosTodos.map(function(v) { return { value: v.ID, label: v.PLACA + ' — ' + (v.MODELO || '') }; })));\n    tplFrota_popularSelect_('tplFrota_mu_veiculo', frotaState.veiculosTodos.map(function(v) { return { value: v.ID, label: v.PLACA + ' — ' + (v.MODELO || '') }; }));\n    tplFrota_popularSelect_('tplFrota_mf_veiculo', [{ value: '', label: 'Todos os veículos' }].concat(frotaState.veiculosTodos.map(function(v) { return { value: v.ID, label: v.PLACA + ' — ' + (v.MODELO || '') }; })));\n    tplFrota_popularSelect_('tplFrota_ab_veiculo', frotaState.veiculosTodos.map(function(v) { return { value: v.ID, label: v.PLACA + ' — ' + (v.MODELO || '') }; }));\n    tplFrota_popularSelect_('tplFrota_af_veiculo', [{ value: '', label: 'Todos os veículos' }].concat(frotaState.veiculosTodos.map(function(v) { return { value: v.ID, label: v.PLACA + ' — ' + (v.MODELO || '') }; })));\n    tplFrota_popularSelect_('tplFrota_rel_veiculo', [{ value: '', label: 'Toda a frota (relatório geral)' }].concat(frotaState.veiculosTodos.map(function(v) { return { value: v.ID, label: v.PLACA + ' — ' + (v.MODELO || '') }; })));\n  }).catch(function(err) { console.error(err); });\n}\n\nfunction tplFrota_souGestor_() {\n  var perfil = (typeof USER_CONTEXT !== 'undefined' && USER_CONTEXT && USER_CONTEXT.perfil) ? String(USER_CONTEXT.perfil).toUpperCase() : '';\n  return ['ADMIN', 'GESTOR', 'DIRETORIA'].indexOf(perfil) !== -1;\n}\n\nfunction tplFrota_renderVeiculosTabela_() {\n  var el = document.getElementById('tplFrota_veiculosTabela');\n  if (!el) return;\n  var souGestor = tplFrota_souGestor_();\n  var btnCadastrar = document.getElementById('tplFrota_btnCadastrarVeiculo');\n  if (btnCadastrar) btnCadastrar.style.display = souGestor ? '' : 'none';\n  if (!frotaState.veiculosTodos.length) { el.innerHTML = '<span class=\"muted\">Nenhum veículo cadastrado ainda.</span>'; return; }\n  var linhas = frotaState.veiculosTodos.map(function(v) {\n    var acao = v.STATUS === 'INATIVO'\n      ? '<button class=\"btn btn-sm\" onclick=\"tplFrota_reativarVeiculo(\\'' + v.ID + '\\')\">Reativar</button>'\n      : '<button class=\"btn btn-sm btn-danger\" onclick=\"tplFrota_inativarVeiculo(\\'' + v.ID + '\\')\">Inativar</button>';\n    if (souGestor) acao = '<button class=\"btn btn-sm\" onclick=\"tplFrota_abrirEditarVeiculo(\\'' + v.ID + '\\')\">Editar</button> ' + acao;\n    return '<tr><td>' + v.PLACA + '</td><td>' + (v.MODELO || '') + ' ' + (v.MARCA || '') + '</td><td>' + (v.KM_ATUAL || 0) + ' km</td><td>' + (v.SITUACAO || v.STATUS) + (v.CONDUTOR_NOME ? '<br>Retirado por: ' + escapeHtml_(v.CONDUTOR_NOME) : '') + '</td><td>' + acao + '</td></tr>';\n  }).join('');\n  el.innerHTML = '<div class=\"tabela-wrap\"><table class=\"resultado-table\"><thead><tr><th>Placa</th><th>Modelo/Marca</th><th>KM</th><th>Status</th><th>Ações</th></tr></thead><tbody>' + linhas + '</tbody></table></div>';\n}\n\nfunction tplFrota_abrirEditarVeiculo(id) {\n  var v = (frotaState.veiculosTodos || []).find(function(x) { return x.ID === id; });\n  if (!v) return;\n  document.getElementById('tplFrota_ve_id').value = v.ID;\n  document.getElementById('tplFrota_ve_placa').value = v.PLACA || '';\n  document.getElementById('tplFrota_ve_modelo').value = v.MODELO || '';\n  document.getElementById('tplFrota_ve_marca').value = v.MARCA || '';\n  document.getElementById('tplFrota_ve_ano').value = v.ANO || '';\n  document.getElementById('tplFrota_ve_cor').value = v.COR || '';\n  document.getElementById('tplFrota_ve_km').value = v.KM_ATUAL || 0;\n  document.getElementById('tplFrota_veiculoEditar').classList.remove('hidden');\n}\n\nfunction tplFrota_fecharEditarVeiculo() {\n  document.getElementById('tplFrota_veiculoEditar').classList.add('hidden');\n}\n\nfunction tplFrota_salvarEdicaoVeiculo() {\n  var payload = {\n    id: document.getElementById('tplFrota_ve_id').value,\n    placa: document.getElementById('tplFrota_ve_placa').value,\n    modelo: document.getElementById('tplFrota_ve_modelo').value,\n    marca: document.getElementById('tplFrota_ve_marca').value,\n    ano: document.getElementById('tplFrota_ve_ano').value,\n    cor: document.getElementById('tplFrota_ve_cor').value,\n    kmAtual: document.getElementById('tplFrota_ve_km').value\n  };\n  tplFrota_chamarApi('apiAtualizarVeiculo', payload).then(function() {\n    tplFrota_fecharEditarVeiculo();\n    tplFrota_carregarVeiculos_();\n  }).catch(function(err) { tplFrota_erro('tplFrota_veiculoEditarStatus', err); });\n}\n\nfunction tplFrota_abrirNovoVeiculo() { document.getElementById('tplFrota_veiculoNovo').classList.remove('hidden'); }\n\nfunction tplFrota_criarVeiculo() {\n  var payload = {\n    placa: document.getElementById('tplFrota_v_placa').value,\n    modelo: document.getElementById('tplFrota_v_modelo').value,\n    marca: document.getElementById('tplFrota_v_marca').value,\n    ano: document.getElementById('tplFrota_v_ano').value,\n    cor: document.getElementById('tplFrota_v_cor').value,\n    kmAtual: document.getElementById('tplFrota_v_km').value\n  };\n  tplFrota_chamarApi('apiCriarVeiculo', payload).then(function() {\n    document.getElementById('tplFrota_veiculoNovo').classList.add('hidden');\n    ['tplFrota_v_placa','tplFrota_v_modelo','tplFrota_v_marca','tplFrota_v_ano','tplFrota_v_cor'].forEach(function(id) { document.getElementById(id).value = ''; });\n    document.getElementById('tplFrota_v_km').value = '0';\n    tplFrota_carregarVeiculos_();\n  }).catch(function(err) { tplFrota_erro('tplFrota_veiculoStatus', err); });\n}\n\nfunction tplFrota_inativarVeiculo(id) { tplFrota_chamarApi('apiInativarVeiculo', { id: id }).then(tplFrota_carregarVeiculos_); }\nfunction tplFrota_reativarVeiculo(id) { tplFrota_chamarApi('apiReativarVeiculo', { id: id }).then(tplFrota_carregarVeiculos_); }\n\n// ---------------- Condutores ----------------\nfunction tplFrota_carregarCondutores_() {\n  return tplFrota_chamarApi('apiListarCondutoresTodos').then(function(res) {\n    frotaState.condutores = res.items || [];\n    var ativos = frotaState.condutores.filter(function(c) { return c.STATUS !== 'INATIVO'; });\n\n    // Quem não é gestor/admin não escolhe condutor — trava visual condizente\n    // com a trava de verdade no servidor (Frota_apiIniciarViagem ignora o\n    // condutorId enviado por quem não é gestor). Evita a tela sugerir que dá\n    // pra registrar em nome de outra pessoa quando na prática não dá.\n    frotaContextoCondutorUI_('tplFrota_r_condutor').catch(function(err) { tplFrota_erro('tplFrota_retiradaStatus',err); });\n\n    tplFrota_popularSelect_('tplFrota_ab_condutor', [{ value: '', label: '—' }].concat(ativos.map(function(c) { return { value: c.ID, label: c.NOME }; })));\n\n    var el = document.getElementById('tplFrota_condutoresLista');\n    if (el) {\n      el.innerHTML = frotaState.condutores.length\n        ? frotaState.condutores.map(function(c) {\n            var acao = c.STATUS === 'INATIVO'\n              ? '<button class=\"btn btn-sm\" onclick=\"tplFrota_reativarCondutor(\\'' + c.ID + '\\')\">Reativar</button>'\n              : '<button class=\"btn btn-sm btn-danger\" onclick=\"tplFrota_inativarCondutor(\\'' + c.ID + '\\')\">Inativar</button>';\n            var vinculo = c.USUARIO_ID ? ' <span class=\"muted\" style=\"color:var(--accent-2);\">Login vinculado</span>' : '';\n            var cnhLink = c.CNH_ARQUIVO_LINK ? (' — <a href=\"' + c.CNH_ARQUIVO_LINK + '\" target=\"_blank\" rel=\"noopener\">Ver CNH</a>') : '';\n            var btnCnh = '<input type=\"file\" id=\"tplFrota_cnh_' + c.ID + '\" accept=\"image/*,application/pdf\" style=\"display:none;\" onchange=\"tplFrota_anexarCnh_(\\'' + c.ID + '\\')\">' +\n              '<button class=\"btn btn-sm\" onclick=\"document.getElementById(\\'tplFrota_cnh_' + c.ID + '\\').click()\">' + (c.CNH_ARQUIVO_LINK ? 'Trocar CNH' : 'Anexar CNH') + '</button>';\n            return '<div class=\"linha-lista\"><span>' + c.NOME + ' <span class=\"muted\">(' + c.STATUS + ')</span>' + vinculo + cnhLink + '</span>' + btnCnh + acao + '</div>';\n          }).join('')\n        : '<span class=\"muted\">Nenhum condutor cadastrado ainda.</span>';\n    }\n  }).catch(function(err) { console.error(err); });\n}\n\nfunction tplFrota_anexarCnh_(id) {\n  var input = document.getElementById('tplFrota_cnh_' + id);\n  var arquivo = input && input.files && input.files[0];\n  if (!arquivo) return;\n  tplFrota_lerArquivoComoBase64_(arquivo).then(function(lido) {\n    if (!lido) return;\n    tplFrota_chamarApi('apiUploadCnh', { condutorId: id, base64: lido.base64, mimeType: lido.mimeType, nomeArquivo: lido.nomeArquivo }).then(function() {\n      tplFrota_carregarCondutores_();\n    }).catch(function(err) { alert((err && err.message) || 'Falha ao anexar CNH.'); });\n  });\n}\n\nfunction tplFrota_abrirNovoCondutor() {\n  document.getElementById('tplFrota_condutorNovo').classList.remove('hidden');\n  tplFrota_chamarApi('apiListarUsuariosParaVinculo').then(function(res) {\n    var sel = document.getElementById('tplFrota_c_usuario');\n    if (!sel) return;\n    var itens = res.items || [];\n    sel.innerHTML = '<option value=\"\">— Sem login (motorista avulso) —</option>' +\n      itens.map(function(u) { return '<option value=\"' + u.ID + '\" data-nome=\"' + u.NOME + '\">' + u.NOME + ' (' + u.USUARIO + ')</option>'; }).join('');\n  }).catch(function(err) { console.error(err); });\n}\n\nfunction tplFrota_aoSelecionarUsuarioCondutor_() {\n  var sel = document.getElementById('tplFrota_c_usuario');\n  var nomeInput = document.getElementById('tplFrota_c_nome');\n  if (!sel || !nomeInput) return;\n  if (sel.value) {\n    var opt = sel.options[sel.selectedIndex];\n    nomeInput.value = opt.getAttribute('data-nome') || opt.textContent;\n    nomeInput.disabled = true;\n  } else {\n    nomeInput.disabled = false;\n  }\n}\n\nfunction tplFrota_criarCondutor() {\n  var payload = {\n    usuarioId: document.getElementById('tplFrota_c_usuario').value,\n    nome: document.getElementById('tplFrota_c_nome').value,\n    telefone: document.getElementById('tplFrota_c_telefone').value,\n    cnh: document.getElementById('tplFrota_c_cnh').value,\n    cnhValidade: document.getElementById('tplFrota_c_cnhValidade').value\n  };\n  var arquivoInput = document.getElementById('tplFrota_c_cnhArquivo');\n  var arquivo = arquivoInput && arquivoInput.files && arquivoInput.files[0];\n  tplFrota_chamarApi('apiCriarCondutor', payload).then(function(res) {\n    var novoId = res.item && res.item.ID;\n    function finalizarCriacao_() {\n      document.getElementById('tplFrota_condutorNovo').classList.add('hidden');\n      ['tplFrota_c_nome','tplFrota_c_telefone','tplFrota_c_cnh','tplFrota_c_cnhValidade'].forEach(function(id) { document.getElementById(id).value = ''; });\n      document.getElementById('tplFrota_c_nome').disabled = false;\n      document.getElementById('tplFrota_c_usuario').value = '';\n      if (arquivoInput) arquivoInput.value = '';\n      tplFrota_carregarCondutores_();\n    }\n    if (arquivo && novoId) {\n      tplFrota_lerArquivoComoBase64_(arquivo).then(function(lido) {\n        if (!lido) { finalizarCriacao_(); return; }\n        tplFrota_chamarApi('apiUploadCnh', { condutorId: novoId, base64: lido.base64, mimeType: lido.mimeType, nomeArquivo: lido.nomeArquivo })\n          .then(finalizarCriacao_)\n          .catch(function(err) { tplFrota_erro('tplFrota_condutorStatus', err); finalizarCriacao_(); });\n      });\n    } else {\n      finalizarCriacao_();\n    }\n  }).catch(function(err) { tplFrota_erro('tplFrota_condutorStatus', err); });\n}\n\nfunction tplFrota_inativarCondutor(id) { tplFrota_chamarApi('apiInativarCondutor', { id: id }).then(tplFrota_carregarCondutores_); }\nfunction tplFrota_reativarCondutor(id) { tplFrota_chamarApi('apiReativarCondutor', { id: id }).then(tplFrota_carregarCondutores_); }\n\n// ---------------- Retiradas em andamento / Alertas ----------------\nfunction tplFrota_carregarEmAndamento_() {\n  carregarSituacaoFrotaUI_();\n  return tplFrota_chamarApi('apiListarViagensEmAndamento').then(function(res) {\n    frotaState.emAndamento = res.items || [];\n    var el = document.getElementById('tplFrota_emAndamentoWrap');\n    if (!el) return;\n    el.innerHTML = frotaState.emAndamento.length\n      ? frotaState.emAndamento.map(function(m) {\n          return '<div class=\"linha-lista\">' +\n            '<span><strong>' + m.veiculoPlaca + '</strong> — ' + m.condutorNome + ' — saiu ' + m.dataSaida + ' ' + m.horaSaida + ' (KM ' + m.kmSaida + ')</span>' +\n            '<button class=\"btn btn-sm btn-primary\" onclick=\"tplFrota_abrirDevolucao_(\\'' + m.id + '\\')\">Registrar Devolução</button></div>';\n        }).join('')\n      : '<span class=\"muted\">Nenhum veículo com retirada em aberto.</span>';\n  }).catch(function(err) { console.error(err); });\n}\n\nfunction tplFrota_carregarAlertas_() {\n  return tplFrota_chamarApi('apiListarAlertasManutencao').then(function(res) {\n    var el = document.getElementById('tplFrota_alertasWrap');\n    if (!el) return;\n    var itens = res.items || [];\n    el.innerHTML = itens.length\n      ? itens.map(function(a) {\n          var critico = a.status === 'VENCIDO';\n          var generoOk = a.categoria === 'DOCUMENTO' ? 'VENCIDO' : 'VENCIDA';\n          var prefixo = a.categoria === 'CNH' ? 'Condutor' : 'Veículo';\n          return '<div class=\"alert-box ' + (critico ? 'error' : 'info') + '\">' + '<strong>' + (critico ? 'Vencido' : 'A vencer') + '</strong> · ' + prefixo + ' <strong>' + a.veiculoPlaca + '</strong> — ' + a.tipoLabel + (critico ? (' ' + generoOk) : ' vencendo em breve') + '</div>';\n        }).join('')\n      : '<div class=\"alert-box success\">Nenhuma manutenção vencendo ou vencida.</div>';\n  }).catch(function(err) { console.error(err); });\n}\n\n// ---------------- Documentos do veículo ----------------\nfunction tplFrota_carregarDocumentos_() {\n  var filtroEl = document.getElementById('tplFrota_df_veiculo');\n  var veiculoId = filtroEl ? filtroEl.value : '';\n  return tplFrota_chamarApi('apiListarDocumentos', { veiculoId: veiculoId }).then(function(res) {\n    frotaState.documentos = res.items || [];\n    tplFrota_renderDocumentosTabela_();\n  }).catch(function(err) { console.error(err); });\n}\n\nfunction tplFrota_renderDocumentosTabela_() {\n  var el = document.getElementById('tplFrota_documentosTabela');\n  if (!el) return;\n  var itens = frotaState.documentos || [];\n  if (!itens.length) { el.innerHTML = '<span class=\"muted\">Nenhum documento anexado ainda.</span>'; return; }\n  var linhas = itens.map(function(d) {\n    var badge = d.status === 'VENCIDO' ? '<span style=\"color:#f2b8b8;font-weight:700;\">VENCIDO</span>'\n      : d.status === 'VENCENDO' ? '<span style=\"color:#e8c473;font-weight:700;\">VENCENDO</span>'\n      : d.status === 'OK' ? '<span style=\"color:#b9dec8;\">OK</span>'\n      : '<span class=\"muted\">sem validade</span>';\n    return '<tr><td>' + d.veiculoPlaca + '</td><td>' + d.TIPO_DOCUMENTO + '</td><td>' + (d.VALIDADE || '-') + '</td><td>' + badge + '</td>' +\n      '<td><a href=\"' + d.LINK + '\" target=\"_blank\" rel=\"noopener\">Abrir</a></td>' +\n      '<td><button class=\"btn btn-sm btn-danger\" onclick=\"tplFrota_excluirDocumento(\\'' + d.ID + '\\')\">Excluir</button></td></tr>';\n  }).join('');\n  el.innerHTML = '<div class=\"tabela-wrap\"><table class=\"resultado-table\"><thead><tr><th>Veículo</th><th>Tipo</th><th>Validade</th><th>Status</th><th>Arquivo</th><th>Ações</th></tr></thead><tbody>' + linhas + '</tbody></table></div>';\n}\n\nfunction tplFrota_abrirNovoDocumento() { document.getElementById('tplFrota_documentoNovo').classList.remove('hidden'); }\n\nfunction tplFrota_uploadDocumento() {\n  var input = document.getElementById('tplFrota_dc_arquivoInput');\n  var arquivo = input && input.files && input.files[0];\n  if (!arquivo) { tplFrota_erro('tplFrota_documentoStatus', new Error('Selecione o arquivo.')); return; }\n  tplFrota_lerArquivoComoBase64_(arquivo).then(function(lido) {\n    if (!lido) { tplFrota_erro('tplFrota_documentoStatus', new Error('Falha ao ler o arquivo.')); return; }\n    var payload = {\n      veiculoId: document.getElementById('tplFrota_dc_veiculo').value,\n      tipoDocumento: document.getElementById('tplFrota_dc_tipo').value,\n      validade: document.getElementById('tplFrota_dc_validade').value,\n      observacoes: document.getElementById('tplFrota_dc_observacoes').value,\n      base64: lido.base64, mimeType: lido.mimeType, nomeArquivo: lido.nomeArquivo\n    };\n    tplFrota_chamarApi('apiUploadDocumento', payload).then(function() {\n      document.getElementById('tplFrota_documentoNovo').classList.add('hidden');\n      input.value = '';\n      document.getElementById('tplFrota_dc_validade').value = '';\n      document.getElementById('tplFrota_dc_observacoes').value = '';\n      tplFrota_carregarDocumentos_();\n    }).catch(function(err) { tplFrota_erro('tplFrota_documentoStatus', err); });\n  });\n}\n\nfunction tplFrota_excluirDocumento(id) {\n  tplFrota_chamarApi('apiExcluirDocumento', { id: id }).then(tplFrota_carregarDocumentos_).catch(function(err) { tplFrota_erro('tplFrota_documentoStatus', err); });\n}\n\n// ---------------- Multas ----------------\nfunction tplFrota_carregarMultas_() {\n  var filtroEl = document.getElementById('tplFrota_mf_veiculo');\n  var veiculoId = filtroEl ? filtroEl.value : '';\n  return tplFrota_chamarApi('apiListarMultas', { veiculoId: veiculoId }).then(function(res) {\n    frotaState.multas = res.items || [];\n    tplFrota_renderMultasTabela_();\n  }).catch(function(err) { console.error(err); });\n}\n\nfunction tplFrota_renderMultasTabela_() {\n  var el = document.getElementById('tplFrota_multasTabela');\n  if (!el) return;\n  var itens = frotaState.multas || [];\n  if (!itens.length) { el.innerHTML = '<span class=\"muted\">Nenhuma multa registrada ainda.</span>'; return; }\n  var opcoesCondutor = frotaState.condutores.map(function(c) { return '<option value=\"' + c.ID + '\">' + c.NOME + '</option>'; }).join('');\n  var linhas = itens.map(function(m) {\n    var valorFmt = 'R$ ' + Number(m.VALOR || 0).toFixed(2).replace('.', ',');\n    var condutorHtml;\n    if (m.condutorNome) {\n      var badgeTxt = m.STATUS_CRUZAMENTO === 'ENCONTRADO' ? 'automático' : (m.STATUS_CRUZAMENTO === 'MANUAL' ? 'manual' : 'conferir');\n      var badgeCor = m.STATUS_CRUZAMENTO === 'ENCONTRADO' ? '#b9dec8' : (m.STATUS_CRUZAMENTO === 'MANUAL' ? '#bcd6ea' : '#e8c473');\n      condutorHtml = m.condutorNome + ' <span style=\"color:' + badgeCor + ';font-size:11px;\">(' + badgeTxt + ')</span>';\n    } else {\n      condutorHtml = '<span style=\"color:#f2b8b8;\">Não identificado</span>';\n    }\n    condutorHtml += '<div class=\"form-row\" style=\"margin-top:6px;\">' +\n      '<select id=\"tplFrota_mc_' + m.ID + '\" style=\"font-size:11px;padding:4px;\">' + opcoesCondutor + '</select>' +\n      '<button class=\"btn btn-sm\" onclick=\"tplFrota_indicarCondutorMulta(\\'' + m.ID + '\\')\">Indicar</button>' +\n      '</div>';\n    var statusSel = '<select onchange=\"tplFrota_atualizarStatusMulta(\\'' + m.ID + '\\', this.value)\">' +\n      ['ABERTA', 'PAGA', 'RECORRIDA', 'CANCELADA'].map(function(s) { return '<option value=\"' + s + '\"' + (s === m.STATUS ? ' selected' : '') + '>' + s + '</option>'; }).join('') +\n      '</select>';\n    var acoes = '';\n    if (m.LINK_DOCUMENTO) acoes += '<a href=\"' + m.LINK_DOCUMENTO + '\" target=\"_blank\" rel=\"noopener\">Ver doc.</a> ';\n    acoes += '<button class=\"btn btn-sm\" onclick=\"tplFrota_recruzarMulta(\\'' + m.ID + '\\')\">Recruzar</button> ';\n    acoes += '<button class=\"btn btn-sm btn-danger\" onclick=\"tplFrota_excluirMulta(\\'' + m.ID + '\\')\">Excluir</button>';\n    return '<tr><td>' + m.veiculoPlaca + '</td><td>' + m.DATA_INFRACAO + ' ' + m.HORA_INFRACAO + '</td><td>' + valorFmt + '</td><td>' + condutorHtml + '</td><td>' + statusSel + '</td><td><div class=\"tabela-acoes\">' + acoes + '</div></td></tr>';\n  }).join('');\n  el.innerHTML = '<div class=\"tabela-wrap\"><table class=\"resultado-table\"><thead><tr><th>Veículo</th><th>Data/Hora</th><th>Valor</th><th>Condutor</th><th>Status</th><th>Ações</th></tr></thead><tbody>' + linhas + '</tbody></table></div>';\n}\n\nfunction tplFrota_abrirNovaMulta() { document.getElementById('tplFrota_multaNovo').classList.remove('hidden'); }\n\nfunction tplFrota_registrarMulta() {\n  var input = document.getElementById('tplFrota_mu_arquivoInput');\n  var arquivo = input && input.files && input.files[0];\n  var payload = {\n    veiculoId: document.getElementById('tplFrota_mu_veiculo').value,\n    dataInfracao: document.getElementById('tplFrota_mu_data').value,\n    horaInfracao: document.getElementById('tplFrota_mu_hora').value,\n    local: document.getElementById('tplFrota_mu_local').value,\n    descricao: document.getElementById('tplFrota_mu_descricao').value,\n    valor: document.getElementById('tplFrota_mu_valor').value,\n    pontos: document.getElementById('tplFrota_mu_pontos').value,\n    orgaoAutuador: document.getElementById('tplFrota_mu_orgao').value,\n    numeroAit: document.getElementById('tplFrota_mu_ait').value,\n    vencimento: document.getElementById('tplFrota_mu_vencimento').value,\n    observacoes: document.getElementById('tplFrota_mu_observacoes').value\n  };\n\n  function enviarMulta_(payloadFinal) {\n    tplFrota_chamarApi('apiRegistrarMulta', payloadFinal).then(function(res) {\n      document.getElementById('tplFrota_multaNovo').classList.add('hidden');\n      ['tplFrota_mu_data','tplFrota_mu_hora','tplFrota_mu_local','tplFrota_mu_descricao','tplFrota_mu_valor','tplFrota_mu_pontos','tplFrota_mu_orgao','tplFrota_mu_ait','tplFrota_mu_vencimento','tplFrota_mu_observacoes'].forEach(function(id) { document.getElementById(id).value = ''; });\n      if (input) input.value = '';\n      var cruz = res.cruzamento || {};\n      var msg = cruz.statusCruzamento === 'ENCONTRADO' ? 'Multa registrada — condutor identificado automaticamente.'\n        : cruz.statusCruzamento === 'MULTIPLOS' ? 'Multa registrada — mais de uma retirada cobre esse horário, confira o condutor sugerido na tabela.'\n        : cruz.statusCruzamento === 'NAO_ENCONTRADO' ? 'Multa registrada — nenhuma retirada encontrada nesse horário, indique o condutor manualmente na tabela.'\n        : 'Multa registrada.';\n      tplFrota_msg('tplFrota_multaStatus', cruz.statusCruzamento === 'ENCONTRADO' ? 'success' : 'info', msg);\n      tplFrota_carregarMultas_();\n    }).catch(function(err) { tplFrota_erro('tplFrota_multaStatus', err); });\n  }\n\n  if (arquivo) {\n    tplFrota_lerArquivoComoBase64_(arquivo).then(function(lido) {\n      if (!lido) { tplFrota_erro('tplFrota_multaStatus', new Error('Falha ao ler o arquivo.')); return; }\n      payload.base64 = lido.base64; payload.mimeType = lido.mimeType; payload.nomeArquivo = lido.nomeArquivo;\n      enviarMulta_(payload);\n    });\n  } else {\n    enviarMulta_(payload);\n  }\n}\n\nfunction tplFrota_indicarCondutorMulta(id) {\n  var sel = document.getElementById('tplFrota_mc_' + id);\n  if (!sel) return;\n  tplFrota_chamarApi('apiIndicarCondutorMulta', { id: id, condutorId: sel.value }).then(tplFrota_carregarMultas_).catch(function(err) { tplFrota_erro('tplFrota_multaStatus', err); });\n}\n\nfunction tplFrota_atualizarStatusMulta(id, status) {\n  tplFrota_chamarApi('apiAtualizarStatusMulta', { id: id, status: status }).then(tplFrota_carregarMultas_).catch(function(err) { tplFrota_erro('tplFrota_multaStatus', err); });\n}\n\nfunction tplFrota_recruzarMulta(id) {\n  tplFrota_chamarApi('apiRecruzarMulta', { id: id }).then(tplFrota_carregarMultas_).catch(function(err) { tplFrota_erro('tplFrota_multaStatus', err); });\n}\n\nfunction tplFrota_excluirMulta(id) {\n  tplFrota_chamarApi('apiExcluirMulta', { id: id }).then(tplFrota_carregarMultas_).catch(function(err) { tplFrota_erro('tplFrota_multaStatus', err); });\n}\n\n// ---------------- Abastecimentos ----------------\nfunction tplFrota_carregarAbastecimentos_() {\n  var filtroEl = document.getElementById('tplFrota_af_veiculo');\n  var veiculoId = filtroEl ? filtroEl.value : '';\n  return tplFrota_chamarApi('apiListarAbastecimentos', { veiculoId: veiculoId }).then(function(res) {\n    frotaState.abastecimentos = res.items || [];\n    tplFrota_renderAbastecimentosTabela_();\n  }).catch(function(err) { console.error(err); });\n}\n\nfunction tplFrota_renderAbastecimentosTabela_() {\n  var el = document.getElementById('tplFrota_abastecimentosTabela');\n  if (!el) return;\n  var itens = frotaState.abastecimentos || [];\n  if (!itens.length) { el.innerHTML = '<span class=\"muted\">Nenhum abastecimento registrado ainda.</span>'; return; }\n  var linhas = itens.map(function(a) {\n    var litros = Number(a.LITROS || 0);\n    var valor = Number(a.VALOR || 0);\n    var precoLitro = litros > 0 ? (valor / litros) : 0;\n    var acoes = '';\n    if (a.COMPROVANTE_LINK) acoes += '<a href=\"' + a.COMPROVANTE_LINK + '\" target=\"_blank\" rel=\"noopener\">Ver comprovante</a> ';\n    acoes += '<button class=\"btn btn-sm btn-danger\" onclick=\"tplFrota_excluirAbastecimento(\\'' + a.ID + '\\')\">Excluir</button>';\n    return '<tr>' +\n      '<td>' + a.veiculoPlaca + '</td>' +\n      '<td>' + a.DATA + '</td>' +\n      '<td>' + (a.KM || '-') + '</td>' +\n      '<td>' + a.TIPO_COMBUSTIVEL + '</td>' +\n      '<td>' + litros.toFixed(2).replace('.', ',') + ' L</td>' +\n      '<td>R$ ' + valor.toFixed(2).replace('.', ',') + '</td>' +\n      '<td>R$ ' + precoLitro.toFixed(3).replace('.', ',') + '/L</td>' +\n      '<td>' + (a.condutorNome || '-') + '</td>' +\n      '<td><div class=\"tabela-acoes\">' + acoes + '</div></td>' +\n      '</tr>';\n  }).join('');\n  el.innerHTML = '<div class=\"tabela-wrap\"><table class=\"resultado-table\"><thead><tr><th>Veículo</th><th>Data</th><th>KM</th><th>Combustível</th><th>Litros</th><th>Valor</th><th>Preço/L</th><th>Condutor</th><th>Ações</th></tr></thead><tbody>' + linhas + '</tbody></table></div>';\n}\n\nfunction tplFrota_abrirNovoAbastecimento() { document.getElementById('tplFrota_abastecimentoNovo').classList.remove('hidden'); }\n\nfunction tplFrota_registrarAbastecimento() {\n  var input = document.getElementById('tplFrota_ab_arquivoInput');\n  var arquivo = input && input.files && input.files[0];\n  var payload = {\n    veiculoId: document.getElementById('tplFrota_ab_veiculo').value,\n    condutorId: document.getElementById('tplFrota_ab_condutor').value,\n    data: document.getElementById('tplFrota_ab_data').value,\n    km: document.getElementById('tplFrota_ab_km').value,\n    tipoCombustivel: document.getElementById('tplFrota_ab_tipo').value,\n    litros: document.getElementById('tplFrota_ab_litros').value,\n    valor: document.getElementById('tplFrota_ab_valor').value,\n    posto: document.getElementById('tplFrota_ab_posto').value\n  };\n\n  function enviarAbastecimento_(payloadFinal) {\n    tplFrota_chamarApi('apiRegistrarAbastecimento', payloadFinal).then(function() {\n      document.getElementById('tplFrota_abastecimentoNovo').classList.add('hidden');\n      ['tplFrota_ab_data','tplFrota_ab_km','tplFrota_ab_litros','tplFrota_ab_valor','tplFrota_ab_posto'].forEach(function(id) { document.getElementById(id).value = ''; });\n      if (input) input.value = '';\n      tplFrota_carregarAbastecimentos_();\n    }).catch(function(err) { tplFrota_erro('tplFrota_abastecimentoStatus', err); });\n  }\n\n  if (arquivo) {\n    tplFrota_lerArquivoComoBase64_(arquivo).then(function(lido) {\n      if (!lido) { tplFrota_erro('tplFrota_abastecimentoStatus', new Error('Falha ao ler o arquivo.')); return; }\n      payload.base64 = lido.base64; payload.mimeType = lido.mimeType; payload.nomeArquivo = lido.nomeArquivo;\n      enviarAbastecimento_(payload);\n    });\n  } else {\n    enviarAbastecimento_(payload);\n  }\n}\n\nfunction tplFrota_excluirAbastecimento(id) {\n  tplFrota_chamarApi('apiExcluirAbastecimento', { id: id }).then(tplFrota_carregarAbastecimentos_).catch(function(err) { tplFrota_erro('tplFrota_abastecimentoStatus', err); });\n}\n\n// ---------------- Fotos (retirada/devolução) ----------------\nfunction tplFrota_onFotosSelecionadas_(qual) {\n  var input = document.getElementById(qual === 'retirada' ? 'tplFrota_r_fotosInput' : 'tplFrota_d_fotosInput');\n  var arquivos = Array.prototype.slice.call(input.files || []).slice(0, 10);\n  var comprimir = typeof frotaComprimirImagem_ === 'function' ? frotaComprimirImagem_ : tplFrota_lerArquivoComoBase64_;\n  Promise.all(arquivos.map(function(f) { return comprimir(f, 1280, 0.72); })).then(function(lidos) {\n    var alvo = qual === 'retirada' ? 'fotosRetirada' : 'fotosDevolucao';\n    lidos.filter(Boolean).forEach(function(f) { frotaState[alvo].push({ base64: f.base64, mimeType: f.mimeType, nomeArquivo: f.nomeArquivo, legenda: '' }); });\n    tplFrota_renderFotos_(qual);\n    input.value = '';\n  });\n}\nfunction tplFrota_atualizarLegendaFoto_(qual, idx, valor) { frotaState[qual === 'retirada' ? 'fotosRetirada' : 'fotosDevolucao'][idx].legenda = valor; }\nfunction tplFrota_removerFoto_(qual, idx) {\n  var alvo = qual === 'retirada' ? 'fotosRetirada' : 'fotosDevolucao';\n  frotaState[alvo].splice(idx, 1);\n  tplFrota_renderFotos_(qual);\n}\nfunction tplFrota_renderFotos_(qual) {\n  var el = document.getElementById(qual === 'retirada' ? 'tplFrota_r_fotosLista' : 'tplFrota_d_fotosLista');\n  var lista = frotaState[qual === 'retirada' ? 'fotosRetirada' : 'fotosDevolucao'];\n  if (!el) return;\n  el.innerHTML = lista.map(function(f, i) {\n    return '<div class=\"foto-thumb\"><img src=\"data:' + f.mimeType + ';base64,' + f.base64 + '\">' +\n      '<input placeholder=\"Legenda (opcional)\" value=\"' + f.legenda + '\" oninput=\"tplFrota_atualizarLegendaFoto_(\\'' + qual + '\\',' + i + ',this.value)\">' +\n      '<button class=\"btn btn-sm btn-danger\" onclick=\"tplFrota_removerFoto_(\\'' + qual + '\\',' + i + ')\">Remover</button></div>';\n  }).join('');\n}\n\n// ---------------- Retirada ----------------\nfunction tplFrota_registrarRetirada() {\n  var veiculoId = document.getElementById('tplFrota_r_veiculo').value;\n  var veiculoObj = frotaState.veiculos.filter(function(v) { return v.ID === veiculoId; })[0];\n  var payloadBase = {\n    veiculoId: veiculoId,\n    condutorId: document.getElementById('tplFrota_r_condutor').value,\n    dataSaida: document.getElementById('tplFrota_r_data').value,\n    horaSaida: document.getElementById('tplFrota_r_hora').value,\n    kmSaida: document.getElementById('tplFrota_r_km').value,\n    finalidade: document.getElementById('tplFrota_r_finalidade').value,\n    checklist: tplFrota_coletarChecklist_('tplFrota_r_checklist')\n  };\n  var fotos = frotaState.fotosRetirada;\n  var selEl = document.getElementById('tplFrota_r_veiculo');\n  var veiculoLabel = (selEl && selEl.selectedOptions && selEl.selectedOptions[0]) ? selEl.selectedOptions[0].text : 'veículo';\n\n  if (FROTA_ENVIO_ATIVO) return;\n  if (!veiculoId || !payloadBase.condutorId) return tplFrota_msg('tplFrota_retiradaStatus','error','Selecione veículo e condutor.');\n  if (!payloadBase.kmSaida) return tplFrota_msg('tplFrota_retiradaStatus','error','Informe o KM de saída.');\n  tplFrota_msg('tplFrota_retiradaStatus','info','Enviando retirada. Aguarde a confirmação.');\n  return frotaEnviarMovimentacaoUI_('apiIniciarViagem',payloadBase,fotos,veiculoObj ? veiculoObj.PLACA : '').then(function() {\n    ['tplFrota_r_km','tplFrota_r_finalidade'].forEach(function(id) { var el=document.getElementById(id); if(el) el.value=''; });\n    frotaState.fotosRetirada=[];\n    tplFrota_renderFotos_('retirada');\n    tplFrota_renderChecklist_('tplFrota_r_checklist');\n    tplFrota_preencherAgora_('retirada');\n    tplFrota_msg('tplFrota_retiradaStatus','success','Retirada confirmada. Veículo em uso por este condutor.');\n    tplFrota_carregarVeiculos_(); tplFrota_carregarEmAndamento_();\n  }).catch(function(err) { tplFrota_erro('tplFrota_retiradaStatus',err); });\n}\n\n// ---------------- Devolução ----------------\nfunction tplFrota_abrirDevolucao_(movimentacaoId) {\n  var mov = frotaState.emAndamento.filter(function(m) { return m.id === movimentacaoId; })[0];\n  if (!mov) return;\n  frotaState.movimentacaoDevolucaoAtual = movimentacaoId;\n  document.getElementById('tplFrota_devolucaoInfo').innerHTML =\n    'Veículo <strong>' + mov.veiculoPlaca + '</strong> — condutor ' + mov.condutorNome + ' — saiu em ' + mov.dataSaida + ' ' + mov.horaSaida + ' (KM ' + mov.kmSaida + ')';\n  document.getElementById('tplFrota_panel_devolucao').classList.remove('hidden');\n  document.getElementById('tplFrota_panel_devolucao').scrollIntoView({ behavior: 'smooth', block: 'start' });\n\n  tplFrota_preencherAgora_('devolucao');}\n\nfunction tplFrota_cancelarDevolucao_() {\n  frotaState.movimentacaoDevolucaoAtual = null;\n  document.getElementById('tplFrota_panel_devolucao').classList.add('hidden');\n}\n\nfunction tplFrota_registrarDevolucao() {\n  if (!frotaState.movimentacaoDevolucaoAtual) return;\n  var movAtual = frotaState.emAndamento.filter(function(m) { return m.id === frotaState.movimentacaoDevolucaoAtual; })[0];\n  var payloadBase = {\n    movimentacaoId: frotaState.movimentacaoDevolucaoAtual,\n    dataChegada: document.getElementById('tplFrota_d_data').value,\n    horaChegada: document.getElementById('tplFrota_d_hora').value,\n    kmChegada: document.getElementById('tplFrota_d_km').value,\n    checklist: tplFrota_coletarChecklist_('tplFrota_d_checklist'),\n    observacoes: document.getElementById('tplFrota_d_observacoes').value\n  };\n  var fotos = frotaState.fotosDevolucao;\n  var infoEl = document.getElementById('tplFrota_devolucaoInfo');\n  var infoLabel = infoEl ? infoEl.textContent : 'veículo';\n\n  if (FROTA_ENVIO_ATIVO) return;\n  if (!payloadBase.kmChegada) return tplFrota_msg('tplFrota_devolucaoStatus','error','Informe o KM de chegada.');\n  tplFrota_msg('tplFrota_devolucaoStatus','info','Enviando devolução. Aguarde a confirmação.');\n  return frotaEnviarMovimentacaoUI_('apiFinalizarViagem',payloadBase,fotos,movAtual ? movAtual.veiculoPlaca : '').then(function() {\n    frotaState.fotosDevolucao=[]; tplFrota_renderFotos_('devolucao');\n    tplFrota_renderChecklist_('tplFrota_d_checklist');\n    tplFrota_cancelarDevolucao_();\n    tplFrota_toast_(true,'Devolução registrada',infoLabel);\n    tplFrota_carregarVeiculos_(); tplFrota_carregarEmAndamento_();\n  }).catch(function(err) { tplFrota_erro('tplFrota_devolucaoStatus',err); });\n}\n\n// ---------------- Manutenção ----------------\nfunction tplFrota_aoTrocarTipoManutencao_() {\n  var codigo = document.getElementById('tplFrota_m_tipo').value;\n  var tipo = frotaState.tiposManutencao.filter(function(t) { return t.codigo === codigo; })[0];\n  var veiculoId = document.getElementById('tplFrota_m_veiculo').value;\n  var veiculo = frotaState.veiculos.filter(function(v) { return v.ID === veiculoId; })[0];\n  if (!tipo) return;\n  if (tipo.intervaloKm && veiculo) document.getElementById('tplFrota_m_proximaKm').value = Number(veiculo.KM_ATUAL || 0) + tipo.intervaloKm;\n}\n\nfunction tplFrota_registrarManutencao() {\n  var payload = {\n    veiculoId: document.getElementById('tplFrota_m_veiculo').value,\n    tipo: document.getElementById('tplFrota_m_tipo').value,\n    data: document.getElementById('tplFrota_m_data').value,\n    km: document.getElementById('tplFrota_m_km').value,\n    custo: document.getElementById('tplFrota_m_custo').value,\n    oficina: document.getElementById('tplFrota_m_oficina').value,\n    descricao: document.getElementById('tplFrota_m_descricao').value,\n    proximaKm: document.getElementById('tplFrota_m_proximaKm').value,\n    proximaData: document.getElementById('tplFrota_m_proximaData').value\n  };\n  tplFrota_chamarApi('apiRegistrarManutencao', payload).then(function() {\n    tplFrota_msg('tplFrota_manutencaoStatus', 'success', 'Manutenção registrada com sucesso.');\n    ['tplFrota_m_data','tplFrota_m_km','tplFrota_m_custo','tplFrota_m_oficina','tplFrota_m_descricao','tplFrota_m_proximaKm','tplFrota_m_proximaData'].forEach(function(id) { document.getElementById(id).value = ''; });\n    tplFrota_carregarAlertas_();\n  }).catch(function(err) { tplFrota_erro('tplFrota_manutencaoStatus', err); });\n}\n\n// ---------------- Despesa ----------------\n// ---------------- Parada ----------------\nfunction tplFrota_registrarParada() {\n  var payload = {\n    veiculoId: document.getElementById('tplFrota_p_veiculo').value,\n    dataInicio: document.getElementById('tplFrota_p_dataInicio').value,\n    dataFim: document.getElementById('tplFrota_p_dataFim').value,\n    motivo: document.getElementById('tplFrota_p_motivo').value,\n    descricao: document.getElementById('tplFrota_p_descricao').value\n  };\n  tplFrota_chamarApi('apiRegistrarParada', payload).then(function() {\n    tplFrota_msg('tplFrota_paradaStatus', 'success', 'Parada registrada com sucesso.');\n    ['tplFrota_p_dataInicio','tplFrota_p_dataFim','tplFrota_p_motivo','tplFrota_p_descricao'].forEach(function(id) { document.getElementById(id).value = ''; });\n  }).catch(function(err) { tplFrota_erro('tplFrota_paradaStatus', err); });\n}\n\n// ---------------- Histórico ----------------\nfunction tplFrota_buscarHistorico() {\n  var veiculoId = document.getElementById('tplFrota_h_veiculo').value;\n  if (!veiculoId) return;\n  tplFrota_chamarApi('apiHistoricoVeiculo', { veiculoId: veiculoId }).then(function(res) {\n    var el = document.getElementById('tplFrota_historicoWrap');\n    var html = '';\n\n    html += '<h3 style=\"font-size:13px;color:var(--text-strong);margin-top:14px;\">Movimentações</h3>';\n    html += res.movimentacoes.length ? res.movimentacoes.map(function(m) {\n      var fim = m.STATUS === 'FINALIZADO' ? (' → chegada ' + tplFrota_esc(m.DATA_CHEGADA) + ' ' + tplFrota_esc(m.HORA_CHEGADA) + ' (KM ' + tplFrota_esc(m.KM_CHEGADA) + ')') : ' — EM ANDAMENTO';\n      return '<div class=\"linha-lista\"><span>Saída ' + tplFrota_esc(m.DATA_SAIDA) + ' ' + tplFrota_esc(m.HORA_SAIDA) + ' (KM ' + tplFrota_esc(m.KM_SAIDA) + ') — ' + tplFrota_esc(m.condutorNome) + fim + (m.FINALIDADE ? ('<br><span class=\"muted\">Finalidade: ' + tplFrota_esc(m.FINALIDADE) + '</span>') : '') + '</span></div>';\n    }).join('') : '<span class=\"muted\">Nenhuma movimentação.</span>';\n\n    html += '<h3 style=\"font-size:13px;color:var(--text-strong);margin-top:14px;\">Manutenções</h3>';\n    html += res.manutencoes.length ? res.manutencoes.map(function(m) {\n      var tipo = frotaState.tiposManutencao.filter(function(t) { return t.codigo === m.TIPO; })[0];\n      return '<div class=\"linha-lista\"><span>' + m.DATA + ' — ' + (tipo ? tipo.label : m.TIPO) + ' — KM ' + m.KM + ' — R$ ' + m.CUSTO + (m.DESCRICAO ? (' — ' + m.DESCRICAO) : '') + '</span></div>';\n    }).join('') : '<span class=\"muted\">Nenhuma manutenção.</span>';\n\n    html += '<h3 style=\"font-size:13px;color:var(--text-strong);margin-top:14px;\">Despesas</h3>';\n    html += res.despesas.length ? res.despesas.map(function(d) {\n      return '<div class=\"linha-lista\"><span>' + d.DATA + ' — ' + d.TIPO + ' — R$ ' + d.VALOR + (d.DESCRICAO ? (' — ' + d.DESCRICAO) : '') + '</span></div>';\n    }).join('') : '<span class=\"muted\">Nenhuma despesa.</span>';\n\n    html += '<h3 style=\"font-size:13px;color:var(--text-strong);margin-top:14px;\">Paradas</h3>';\n    html += res.paradas.length ? res.paradas.map(function(p) {\n      return '<div class=\"linha-lista\"><span>' + p.DATA_INICIO + (p.DATA_FIM ? (' até ' + p.DATA_FIM) : ' (sem data de fim)') + ' — ' + p.MOTIVO + (p.DESCRICAO ? (' — ' + p.DESCRICAO) : '') + '</span></div>';\n    }).join('') : '<span class=\"muted\">Nenhuma parada.</span>';\n\n    el.innerHTML = html;\n  }).catch(function(err) { tplFrota_erro('tplFrota_historicoWrap', err); });\n}\n\n// ---------------- Manual do Operador ----------------\nfunction tplFrota_manualHtml_() {\n  return `\n<div class=\"wrap manual-wrap\">\n\n  <header class=\"header-card\" style=\"position:static; margin-bottom:24px;\">\n    <div class=\"title-area\">\n      <h1 style=\"margin-bottom:4px;\">Manual do Operador</h1>\n      <p style=\"margin:0;\">Frota — retirada/devolução, checklist de vistoria, manutenção, documentos, abastecimento, multas, relatório e histórico</p>\n    </div>\n    <button type=\"button\" class=\"btn\" onclick=\"tplFrota_voltarDoManual_()\">← Voltar ao sistema</button>\n  </header>\n\n  <div class=\"toc\" id=\"tplFrota_topoManual\">\n    <h2>Índice</h2>\n    <ol>\n      <li><a onclick=\"tplFrota_irParaSecao_('tplFrota_ms1')\">Como usar este manual</a></li>\n      <li><a onclick=\"tplFrota_irParaSecao_('tplFrota_ms2')\">O que este sistema faz</a></li>\n      <li><a onclick=\"tplFrota_irParaSecao_('tplFrota_ms3')\">Versão celular x versão computador</a></li>\n      <li><a onclick=\"tplFrota_irParaSecao_('tplFrota_ms4')\">Veículos e Condutores</a></li>\n      <li><a onclick=\"tplFrota_irParaSecao_('tplFrota_ms5')\">Retirar veículo</a></li>\n      <li><a onclick=\"tplFrota_irParaSecao_('tplFrota_ms6')\">Devolver veículo</a></li>\n      <li><a onclick=\"tplFrota_irParaSecao_('tplFrota_ms7')\">Manutenção e alertas de vencimento</a></li>\n      <li><a onclick=\"tplFrota_irParaSecao_('tplFrota_ms8')\">Documentos do veículo</a></li>\n      <li><a onclick=\"tplFrota_irParaSecao_('tplFrota_ms9')\">Abastecimentos</a></li>\n      <li><a onclick=\"tplFrota_irParaSecao_('tplFrota_ms10')\">Despesas e Paradas</a></li>\n      <li><a onclick=\"tplFrota_irParaSecao_('tplFrota_ms11')\">Multas</a></li>\n      <li><a onclick=\"tplFrota_irParaSecao_('tplFrota_ms12')\">Histórico do veículo</a></li>\n      <li><a onclick=\"tplFrota_irParaSecao_('tplFrota_ms13')\">Relatório da Frota em PDF</a></li>\n      <li><a onclick=\"tplFrota_irParaSecao_('tplFrota_ms14')\">Passo a passo completo</a></li>\n      <li><a onclick=\"tplFrota_irParaSecao_('tplFrota_ms15')\">Erros comuns</a></li>\n      <li><a onclick=\"tplFrota_irParaSecao_('tplFrota_ms16')\">Glossário</a></li>\n    </ol>\n  </div>\n\n  <h2 id=\"tplFrota_ms1\">1. Como usar este manual</h2>\n  <p>Este manual foi escrito para quem <strong>nunca usou o sistema</strong>. Leia na ordem, de cima para baixo, seguindo a tela também de cima para baixo. Se aparecer uma palavra técnica desconhecida, vá direto ao <strong>Glossário</strong> (seção 16).</p>\n\n  <h2 id=\"tplFrota_ms2\">2. O que este sistema faz, em uma frase</h2>\n  <p>Você registra quando pega e quando devolve um veículo da empresa, com uma vistoria (checklist) em cada ponta pra flagrar qualquer problema novo — e o sistema cuida sozinho do resto: avisa quando manutenção, documento ou CNH de algum condutor está vencendo, cruza multas com quem estava usando o veículo na hora, calcula o consumo de combustível e monta um relatório completo em PDF sempre que você precisar prestar contas sobre a frota.</p>\n  <div class=\"callout\"><strong>Todas as seções ficam sempre visíveis na tela</strong> — não é um passo a passo obrigatório. Use a seção que precisar, na hora que precisar.</div>\n\n  <h2 id=\"tplFrota_ms3\">3. Versão celular x versão computador</h2>\n  <p>Se você é motorista/operador (não é gestor nem administrador) e está acessando pelo <strong>celular</strong>, a tela é bem enxuta de propósito: só dá pra retirar e devolver veículo. Nada de cadastro, edição, documento, multa, abastecimento ou relatório aparece pra você — é assim pra manter o dia a dia simples.</p>\n  <p>Gestor e Administrador, mesmo pelo celular, continuam vendo a tela completa. Pelo <strong>computador</strong>, todo mundo vê a tela inteira, mas as ações de cadastro/edição (veículo, condutor, documento, multa, abastecimento, manutenção, despesa, parada, relatório) só funcionam pra quem é Gestor ou Administrador — se você tentar sem ter essa permissão, o sistema recusa e explica o motivo.</p>\n  <div class=\"callout\"><strong>Retirar e devolver veículo funciona pra qualquer login</strong>, em qualquer uma das duas versões — é o \"básico\" que todo mundo precisa conseguir fazer.</div>\n\n  <h2 id=\"tplFrota_ms4\">4. Veículos e Condutores</h2>\n  <p>Antes de registrar qualquer retirada, o veículo e o condutor precisam estar cadastrados (uma vez só, depois reaproveita sempre). Use <strong>\"+ Cadastrar novo veículo\"</strong> (placa, modelo, marca, ano, cor, KM atual) e <strong>\"+ Cadastrar novo condutor\"</strong> (nome, telefone, CNH opcional). Um veículo ou condutor que não vai ser mais usado pode ser <strong>Inativado</strong> (some das listas de seleção, mas fica no histórico) em vez de excluído.</p>\n  <p>Ao cadastrar um condutor, você pode (é opcional) <strong>vincular a um usuário do SGO</strong> já existente, escolhendo na lista \"Vincular a um usuário do SGO\". Quando vinculado, o nome do condutor é travado automaticamente igual ao nome cadastrado do login, pra nunca ficar divergente. Esse vínculo também permite anexar a <strong>CNH</strong> do condutor (foto ou PDF) e informar a validade dela — o sistema avisa sozinho quando estiver vencendo, junto com os avisos de manutenção.</p>\n  <div class=\"callout\"><strong>Por que vincular o condutor a um login?</strong> É o que garante que ninguém registre uma retirada em nome de outra pessoa: quando um login que não é gestor/administrador registra uma retirada, o sistema usa automaticamente o condutor vinculado àquele login — nem aparece opção pra escolher outro nome. Só gestor/administrador pode escolher qualquer condutor, pra cobrir exceções (por exemplo, um motorista que esqueceu de registrar e o gestor precisa lançar por ele).</div>\n\n  <h2 id=\"tplFrota_ms5\">5. Retirar veículo</h2>\n  <p>Preencha veículo, data/hora e <strong>KM de saída</strong> (tem que ser igual ou maior que o KM atual do veículo — o sistema recusa um KM menor, provavelmente é erro de digitação). Preencha a finalidade da viagem.</p>\n  <p>Se você não é gestor/administrador, o campo de condutor já vem travado com o seu próprio nome (o do seu login) — não tem como escolher outra pessoa, nem no celular nem no computador.</p>\n  <p>Depois, faça o <strong>checklist de vistoria</strong>: cada item já vem marcado como \"OK\" — desmarque o que estiver com problema e escreva uma observação ao lado. Anexe fotos se quiser registrar evidência visual. Clique em <strong>\"Registrar Retirada\"</strong>.</p>\n  <div class=\"callout\"><strong>O que acontece?</strong> O veículo passa a aparecer em \"Retiradas em andamento\" e some da lista de veículos disponíveis pra retirada, até ser devolvido. Se alguém tentar retirar um veículo que já está em uso, o sistema bloqueia — mesmo que duas pessoas tentem quase ao mesmo tempo.</div>\n\n  <h2 id=\"tplFrota_ms6\">6. Devolver veículo</h2>\n  <p>Na seção \"Retiradas em andamento\", clique em <strong>\"Registrar Devolução\"</strong> do veículo correspondente — abre um formulário já sabendo qual retirada está sendo fechada. Preencha data/hora e <strong>KM de chegada</strong> (tem que ser igual ou maior que o KM de saída registrado). Faça o checklist de vistoria de novo (mesma lista) e anexe fotos se encontrar algum problema novo.</p>\n  <div class=\"callout\"><strong>Por que o checklist se repete na devolução?</strong> Pra você comparar: se um item estava OK na saída e voltou com problema, é fácil perceber que aconteceu durante o uso.</div>\n\n  <h2 id=\"tplFrota_ms7\">7. Manutenção e alertas de vencimento</h2>\n  <p>Registre cada manutenção feita (óleo, pneu, filtro, freio, etc.) com data, KM, custo, oficina e descrição. Ao escolher o <strong>Tipo</strong>, o campo \"Próxima troca — KM\" já vem sugerido automaticamente (KM atual do veículo + intervalo padrão daquele tipo) — você pode ajustar esse número livremente.</p>\n  <div class=\"callout\"><strong>\"Avisos de manutenção\" no topo da tela</strong> mostra, sozinho, quais veículos estão com manutenção, documento (CRLV, seguro, licenciamento, etc.) ou CNH de algum condutor vencendo (até 500 km ou 30 dias de antecedência) ou já vencidos — sem precisar ir conferindo manualmente. O mesmo aviso aparece em destaque no topo do Dashboard do Portal e como bolinha vermelha no menu lateral.</div>\n\n  <h2 id=\"tplFrota_ms8\">8. Documentos do veículo</h2>\n  <p>Cada veículo pode ter documentos anexados pra consulta rápida a qualquer momento — CRLV, Seguro, Licenciamento, IPVA, Laudo de Vistoria, Nota Fiscal ou Outro. Escolha o veículo, o tipo de documento, anexe o arquivo (foto ou PDF) e, se o documento tiver prazo de validade, informe a data.</p>\n  <div class=\"callout\"><strong>Documento sem validade nunca entra no alarme</strong>, de propósito — uma nota fiscal ou um laudo avulso não têm prazo pra vencer. Só documentos com data de validade preenchida entram na checagem automática de vencimento.</div>\n\n  <h2 id=\"tplFrota_ms9\">9. Abastecimentos</h2>\n  <p>Registre cada abastecimento com data, KM no momento, tipo de combustível, litros, valor total, posto e, se quiser, uma foto do comprovante.</p>\n  <div class=\"callout\"><strong>Consumo médio (km/L)</strong> é calculado sozinho pelo sistema, comparando o KM entre abastecimentos consecutivos do mesmo veículo — por isso precisa de pelo menos 2 abastecimentos registrados no período pra aparecer um número. Esse consumo é usado no Relatório da Frota pra mostrar o custo por quilômetro rodado.</div>\n\n  <h2 id=\"tplFrota_ms10\">10. Despesas e Paradas</h2>\n  <p><strong>Despesas:</strong> registre qualquer gasto avulso do veículo (pedágio, estacionamento, lavagem, etc.) com data, valor e descrição.</p>\n  <p><strong>Paradas:</strong> registre períodos em que o veículo ficou fora de uso (acidente, pane, revisão de garantia) — data de início, data de fim (se já souber) e o motivo.</p>\n\n  <h2 id=\"tplFrota_ms11\">11. Multas</h2>\n  <p>Quando chegar uma notificação de multa, lance manualmente os dados: veículo, data e hora da infração, local, descrição, valor, órgão autuador, número do AIT e vencimento — anexe o documento da notificação se quiser.</p>\n  <div class=\"callout\"><strong>Cruzamento automático:</strong> assim que você salva a multa, o sistema cruza sozinho a data/hora da infração com o histórico de retiradas daquele veículo e já indica quem estava com ele naquele momento — sem precisar ir procurar manualmente. Se não encontrar nenhuma retirada compatível, ou encontrar mais de uma (situação rara), a tela avisa e deixa você indicar o condutor manualmente. Cada multa tem um status (Aberta, Paga, Recorrida, Cancelada) que você atualiza direto na lista, e um botão \"Recruzar\" pra tentar de novo se a movimentação foi lançada depois da multa.</div>\n\n  <h2 id=\"tplFrota_ms12\">12. Histórico do veículo</h2>\n  <p>Escolha um veículo e clique em \"Buscar\" — mostra tudo junto: movimentações, manutenções, despesas e paradas, do mais recente pro mais antigo.</p>\n\n  <h2 id=\"tplFrota_ms13\">13. Relatório da Frota em PDF</h2>\n  <p>No topo da tela, escolha o período (data início e fim) e, se quiser um relatório de um veículo só, escolha ele na lista \"Veículo\" — deixando em \"Toda a frota\", gera o relatório de todos os veículos juntos. Clique em <strong>\"Gerar Relatório\"</strong>: abre uma aba nova com o documento pronto pra imprimir ou salvar como PDF (Ctrl+P), e uma cópia fica salva automaticamente no Drive.</p>\n  <p>O relatório <strong>de um veículo</strong> mostra: identificação, todas as retiradas do período, abastecimentos e consumo, despesas, manutenções, situação dos documentos e da CNH do condutor responsável, multas e ocorrências, um resumo com os principais números, uma conclusão redigida por Inteligência Artificial (baseada só nos dados reais do próprio relatório, nunca inventada) e a lista de pendências em aberto.</p>\n  <p>O relatório <strong>geral da frota</strong> mostra os mesmos números de todos os veículos juntos, com gráficos e um ranking de quais veículos estão mais usados/disputados e quais estão ociosos.</p>\n\n  <h2 id=\"tplFrota_ms14\">14. Passo a passo completo</h2>\n  <ol>\n    <li>Cadastre veículos e condutores (uma vez só) — vincule o condutor a um login do SGO se ele for usar o sistema pra registrar.</li>\n    <li>Na retirada: escolha veículo, preencha KM e finalidade, faça o checklist, registre.</li>\n    <li>Na devolução: clique em \"Registrar Devolução\" na retirada em andamento, preencha KM de chegada, faça o checklist de novo, registre.</li>\n    <li>Registre manutenções, documentos, abastecimentos, despesas e paradas conforme forem acontecendo.</li>\n    <li>Quando chegar uma multa, lance os dados e confira quem o sistema identificou.</li>\n    <li>Consulte o histórico de um veículo, ou gere o relatório em PDF, quando precisar.</li>\n  </ol>\n\n  <h2 id=\"tplFrota_ms15\">15. Erros comuns e o que fazer</h2>\n  <table>\n    <tr><th>O que aconteceu</th><th>O que fazer</th></tr>\n    <tr><td>\"O KM de saída não pode ser menor que o KM atual do veículo\"</td><td>Confira o KM atual mostrado na tabela de Veículos antes de preencher</td></tr>\n    <tr><td>\"Este veículo já está com uma retirada em andamento\"</td><td>Finalize a devolução da retirada atual antes de iniciar outra</td></tr>\n    <tr><td>Não aparece nenhum veículo pra retirar</td><td>Todos podem estar em uso no momento — confira \"Retiradas em andamento\"</td></tr>\n    <tr><td>\"Seu usuário não está vinculado a nenhum condutor cadastrado\"</td><td>Peça pro gestor cadastrar um condutor vinculado ao seu login (seção 4)</td></tr>\n    <tr><td>\"Este usuário já está vinculado ao condutor [nome]\"</td><td>Cada login só pode estar vinculado a um único condutor — escolha outro usuário</td></tr>\n    <tr><td>Consumo médio (km/L) não aparece no relatório</td><td>Precisa de pelo menos 2 abastecimentos do mesmo veículo registrados no período escolhido</td></tr>\n  </table>\n\n  <h2 id=\"tplFrota_ms16\">16. Glossário</h2>\n  <table>\n    <tr><th>Termo</th><th>Explicação simples</th></tr>\n    <tr><td>Checklist de vistoria</td><td>Lista de itens do veículo conferidos na retirada e na devolução, pra flagrar problemas</td></tr>\n    <tr><td>Retirada em andamento</td><td>Um veículo que já foi pego mas ainda não foi devolvido</td></tr>\n    <tr><td>Vencendo / Vencida</td><td>Manutenção, documento ou CNH perto do prazo previsto, ou já passado dele</td></tr>\n    <tr><td>Parada</td><td>Período em que o veículo ficou fora de uso</td></tr>\n    <tr><td>Condutor vinculado</td><td>Condutor associado a um login do SGO — garante que só aquela pessoa apareça como responsável quando ela mesma registrar uma retirada</td></tr>\n    <tr><td>Consumo médio (km/L)</td><td>Quantos quilômetros o veículo roda com 1 litro de combustível, calculado a partir dos abastecimentos</td></tr>\n    <tr><td>Cruzamento de multa</td><td>Comparação automática entre a data/hora de uma multa e o histórico de retiradas, pra identificar o condutor responsável</td></tr>\n    <tr><td>Pendência</td><td>Item em aberto que o sistema identificou sozinho (manutenção, documento ou CNH vencendo/vencida) e lista no relatório</td></tr>\n  </table>\n\n  <a class=\"topo-link\" onclick=\"tplFrota_irParaSecao_('tplFrota_topoManual')\">↑ Topo</a>\n</div>\n`;\n}\n</script>\n";function Frota_obterConteudoModulo() {
  return FROTA_CONTEUDO_MODULO;
}
